// Detect password recovery hash SYNCHRONOUSLY at module load time, before Supabase
// has a chance to parse and clear the URL hash. This is the only reliable way to
// intercept the recovery event, because by the time useEffect runs Supabase has
// already removed the hash from the URL.
(function detectRecoveryHash() {
  try {
    const h = window.location.hash;
    const q = window.location.search;
    // Check both the hash (implicit flow) and the query param we set in redirectTo
    if (
      h.includes("type=recovery") || h.includes("type%3Drecovery") ||
      q.includes("recovery=1")
    ) {
      sessionStorage.setItem("tbv-pw-recovery", "1");
    }
  } catch (_) {}
})();

