function HeroSavingsTicker({ className = "" }) {
  const FROM = 400;
  const TO = 75;
  const [value, setValue] = useState(FROM);
  const [pulse, setPulse] = useState(false);
  const [eased, setEased] = useState(0);
  const [linear, setLinear] = useState(0);
  const rafRef = useRef(null);
  const timeoutRef = useRef(null);

  useEffect(() => {
    let cancelled = false;
    const runCycle = () => {
      setValue(FROM);
      setEased(0);
      setLinear(0);
      timeoutRef.current = setTimeout(() => {
        if (cancelled) return;
        const start = performance.now();
        const duration = 1700;
        const step = (now) => {
          if (cancelled) return;
          const p = Math.min(1, (now - start) / duration);
          const e = 1 - Math.pow(1 - p, 3);
          setValue(Math.round(FROM - (FROM - TO) * e));
          setEased(e);
          setLinear(p);
          if (p < 1) {
            rafRef.current = requestAnimationFrame(step);
          } else {
            setPulse(true);
            setTimeout(() => setPulse(false), 500);
            timeoutRef.current = setTimeout(() => {
              if (cancelled) return;
              runCycle();
            }, 1200);
          }
        };
        rafRef.current = requestAnimationFrame(step);
      }, 300);
    };
    runCycle();
    return () => {
      cancelled = true;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const colorStops = [
    { t: 0, h: 0, s: 92, l: 58 },
    { t: 0.16, h: 14, s: 94, l: 55 },
    { t: 0.32, h: 30, s: 96, l: 52 },
    { t: 0.48, h: 45, s: 96, l: 50 },
    { t: 0.62, h: 62, s: 90, l: 48 },
    { t: 0.78, h: 95, s: 78, l: 46 },
    { t: 0.9, h: 140, s: 75, l: 52 },
    { t: 1, h: 152, s: 78, l: 56 },
  ];
  let a = colorStops[0];
  let b = colorStops[colorStops.length - 1];
  for (let i = 0; i < colorStops.length - 1; i++) {
    if (linear >= colorStops[i].t && linear <= colorStops[i + 1].t) {
      a = colorStops[i];
      b = colorStops[i + 1];
      break;
    }
  }
  const span = b.t - a.t || 1;
  const localT = Math.min(1, Math.max(0, (linear - a.t) / span));
  const hue = a.h + (b.h - a.h) * localT;
  const sat = a.s + (b.s - a.s) * localT;
  const light = a.l + (b.l - a.l) * localT;
  const color = `hsl(${hue.toFixed(1)}, ${sat.toFixed(1)}%, ${light.toFixed(1)}%)`;

  return (
    <span className={`inline-flex items-baseline align-middle ${className}`}>
      <span
        className={`text-[16px] font-black tabular-nums transition-transform md:text-2xl ${pulse ? "scale-110" : "scale-100"}`}
        style={{ color, transition: "transform 0.35s cubic-bezier(0.34,1.56,0.64,1)", textShadow: "1px 2px 0 rgba(0,0,0,0.275), 2px 4px 0 rgba(0,0,0,0.225), 3px 6px 0 rgba(0,0,0,0.175), 4px 8px 0 rgba(0,0,0,0.125), 6px 12px 10px rgba(0,0,0,0.15)" }}
      >
        ${value}
      </span>
    </span>
  );
}

function CopyTrackingNumber({ trackingNumber, label = "Tracking Number — Tap to copy" }) {
  const [copied, setCopied] = useState(false);
  function handleCopy() {
    navigator.clipboard.writeText(trackingNumber).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }
  return (
    <div className="mt-3 w-full flex gap-2">
      <button
        onClick={handleCopy}
        className="flex-1 flex items-center justify-between gap-3 rounded-xl border border-emerald-500/40 bg-emerald-500/10 px-4 py-3 text-left transition hover:bg-emerald-500/20 active:scale-[0.98] min-w-0"
      >
        <div className="flex items-center gap-3 min-w-0">
          <span className="text-emerald-400 text-[16px]">→</span>
          <div className="min-w-0">
            <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-emerald-400/80">
              {label}
            </p>
            <p className="font-mono text-[18px] font-black tracking-widest text-emerald-300 truncate">
              {trackingNumber}
            </p>
          </div>
        </div>
        <span className="shrink-0 text-emerald-400/70 text-[18px]">
          {copied ? "✓" : (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>
            </svg>
          )}
        </span>
      </button>
      <a
        href={`https://t.17track.net/en#nums=${encodeURIComponent(trackingNumber)}`}
        target="_blank"
        rel="noopener noreferrer"
        className="flex items-center justify-center gap-2 rounded-xl border border-blue-400/50 bg-blue-700/40 px-6 py-3 transition hover:bg-blue-700/55 active:scale-[0.98] whitespace-nowrap text-[13px] font-bold uppercase tracking-[0.15em] text-white"
      >
        17TRACK
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>
          <polyline points="15 3 21 3 21 9"/>
          <line x1="10" y1="14" x2="21" y2="3"/>
        </svg>
      </a>
    </div>
  );
}

function FedExTrackBlock() {
  const [fedexInput, setFedexInput] = useState("");

  function handleFedEx(e) {
    e.preventDefault();
    const num = fedexInput.trim();
    if (!num) return;
    window.open(`https://www.fedex.com/fedextrack/?trknbr=${encodeURIComponent(num)}`, "_blank", "noopener,noreferrer");
  }

  return (
    <div className="rounded-[1.5rem] border border-white/20 bg-black/20 p-6 shadow-[0_10px_30px_rgba(0,0,0,0.08)] md:rounded-[2rem] md:p-10">
      <h1 className="mb-2 text-center font-semibold uppercase tracking-[0.12em] text-white" style={{fontSize:"clamp(1rem,5.5vw,2.25rem)"}}>
        Track Your Order (FedEx)
      </h1>
      <p className="mb-6 text-center text-[12px] font-semibold uppercase tracking-[0.1em] text-white/50">
        Opens FedEx tracking in a new tab
      </p>
      <form onSubmit={handleFedEx} className="flex flex-col gap-3 sm:flex-row">
        <input
          type="text"
          value={fedexInput}
          onChange={(e) => setFedexInput(e.target.value)}
          placeholder="Enter FedEx tracking number"
          className="flex-1 rounded-full border border-white/20 bg-white/10 px-5 py-3 text-[14px] font-semibold uppercase tracking-[0.06em] text-white placeholder:text-white/50 outline-none focus:border-white/50"
          autoComplete="off"
          spellCheck={false}
        />
        <button
          type="submit"
          disabled={!fedexInput.trim()}
          className="rounded-full bg-[#4d148c] px-6 py-3 text-[13px] font-bold uppercase tracking-[0.18em] text-white transition hover:bg-[#3d0f70] disabled:opacity-50"
        >
          Track
        </button>
      </form>
      <p className="mt-5 text-[12px] leading-relaxed text-white/70 text-center">
        While your package is in transit between countries, FedEx may not show any tracking updates. This is completely normal. During this stage, the shipment is handled by partner carriers, so tracking information will only appear once the package arrives in the destination country and receives its first scan in the FedEx system.
      </p>
    </div>
  );
}

