  useEffect(() => {
    const simpleHash = (str) => {
      let h = 0;
      for (let i = 0; i < str.length; i++) { h = (Math.imul(31, h) + str.charCodeAt(i)) | 0; }
      return h;
    };
    // Don't show if dismissed recently (within 30 min)
    const dismissedAt = Number(localStorage.getItem("updateDismissedAt") || 0);
    if (Date.now() - dismissedAt < 30 * 60 * 1000) return;

    let initialHash = null;
    let pendingHash = null; // must match twice in a row to avoid CDN flicker
    let confirmTimeout = null;
    const check = () => {
      if (initialHash === null) return;
      // Don't recheck if dismissed recently
      const da = Number(localStorage.getItem("updateDismissedAt") || 0);
      if (Date.now() - da < 30 * 60 * 1000) return;
      fetch("/?_=" + Date.now(), {
        cache: "no-store",
        headers: { "Cache-Control": "no-cache, no-store, must-revalidate", "Pragma": "no-cache" },
      })
        .then(r => r.text())
        .then(html => {
          const h = simpleHash(html);
          if (h !== initialHash) {
            if (pendingHash === h) {
              // Same different hash seen twice — real update
              setUpdateAvailable(true);
              if (confirmTimeout) { clearTimeout(confirmTimeout); confirmTimeout = null; }
            } else {
              pendingHash = h;
              // Confirm quickly instead of waiting for the next scheduled
              // check (which could be up to 10 min later, or never if the
              // tab isn't reopened again) — this is what let real updates
              // silently go unconfirmed for most users.
              if (confirmTimeout) clearTimeout(confirmTimeout);
              confirmTimeout = setTimeout(check, 3000);
            }
          } else {
            pendingHash = null;
          }
        })
        .catch(() => {});
    };
    fetch("/?_=" + Date.now(), {
      cache: "no-store",
      headers: { "Cache-Control": "no-cache, no-store, must-revalidate", "Pragma": "no-cache" },
    })
      .then(r => r.text())
      .then(html => { initialHash = simpleHash(html); })
      .catch(() => {});
    // Check every 10 minutes — not 5 seconds
    const iv = setInterval(check, 10 * 60 * 1000);
    // Also check immediately whenever the tab becomes visible/focused again —
    // background tabs get their timers throttled/paused by the browser, so
    // relying only on setInterval means many users never see the prompt.
    const onVisible = () => {
      if (document.visibilityState === "visible") check();
    };
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("focus", onVisible);
    return () => {
      clearInterval(iv);
      if (confirmTimeout) clearTimeout(confirmTimeout);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("focus", onVisible);
    };
  }, []);

