  // Migrates a cart item saved under an old product name/dose/price to the
  // current canonical values so the server-side catalog lookup doesn't reject it
  // and the displayed price always reflects the latest catalog price.
  function migrateCartItem(item) {
    if (!item || typeof item !== "object") return item;
    let { name, dose, ...rest } = item;

    // Normalise name: old short names → current full names
    const NAME_MAP = {
      "retatrutide":          "Retatrutide / GLP-3",
      "tirzepatide":          "Tirzepatide / GLP-2",
      "ghk-cu":               "GHK-CU",
      "ghk-cop":              "GHK-CU",
      "ghk cu":               "GHK-CU",
    };
    const nameKey = String(name || "").trim().toLowerCase();
    if (NAME_MAP[nameKey]) name = NAME_MAP[nameKey];

    // Normalise dose: "20mg" → "20 mg", "10mcg" → "10 mcg", etc.
    if (dose) {
      dose = String(dose).trim().replace(/(\d)\s*([a-zA-Z])/g, (_, n, u) => `${n} ${u.toLowerCase()}`);
    }

    // Re-price from current PRODUCTS_BASE so stale saved prices are corrected.
    const normD = (v) => String(v || "").trim().toLowerCase().replace(/(\d)\s+([a-z])/g, "$1$2");
    const wantsUs = item.fromWarehouse === "us";
    const catalogEntry = PRODUCTS_BASE.find((p) => {
      const pn = p.name.toLowerCase();
      const cn = name.toLowerCase();
      const base = pn.split(" / ")[0].trim();
      return (pn === cn || base === cn) &&
        normD(p.dose) === normD(dose) &&
        (p.warehouse === "us") === wantsUs;
    });
    if (catalogEntry) {
      let currentPrice;
      if (wantsUs) {
        const usOriginal = (catalogEntry.usPriceBase ?? catalogEntry.price) + 5;
        currentPrice = usOriginal;
      } else {
        currentPrice = catalogEntry.price;
      }
      rest = { ...rest, price: currentPrice };
    }

    return { name, dose, ...rest };
  }

  // Load + merge saved cart from Supabase when user logs in
  useEffect(() => {
    if (!currentUser?.email) return;
    supabase.auth.getUser().then(({ data }) => {
      const savedCart = data?.user?.user_metadata?.savedCart;
      if (!Array.isArray(savedCart) || savedCart.length === 0) return;
      setCart((current) => {
        const merged = [...current];
        savedCart.forEach((raw) => {
          const savedItem = migrateCartItem(raw);
          const id = getProductId(savedItem);
          const exists = current.some((item) => getProductId(item) === id);
          if (!exists) merged.push(savedItem);
        });
        return merged;
      });
    });
  }, [currentUser?.email]);

