  function normalizeEmail(value) {
    return String(value || "").trim().toLowerCase();
  }

  const ADMIN_EMAILS = ["support@10bottlevalue.co"];

  function isAdminUser(user = currentUser) {
    return ADMIN_EMAILS.includes(normalizeEmail(user?.email));
  }

  function stripQuoteMarker(text) {
    return String(text || "").replace(/^\[QUOTE:([^\]]*)\]/, "").trim();
  }

  function extractQuoteSnippet(text) {
    const m = String(text || "").match(/^\[QUOTE:([^\]]*)\]/);
    if (!m) return null;
    let raw;
    try { raw = decodeURIComponent(m[1]); } catch { raw = m[1]; }
    try {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === "object" && "text" in parsed) return parsed;
    } catch {}
    return { id: null, side: null, text: raw }; // backward-compat: older quotes stored plain text only
  }

  function makeQuoteSnippet(text, id, side) {
    const clean = stripQuoteMarker(text)
      .replace(/\[IMAGE:[^\]]+\]/g, "📷 Photo")
      .replace(/\[VIDEO:[^\]]+\]/g, "🎥 Video")
      .replace(/\[FILE:[^\]]+\]/g, "📄 File")
      .trim();
    const snippet = clean.length > 120 ? clean.slice(0, 120) + "…" : clean;
    return { id: id ?? null, side: side ?? null, text: snippet };
  }

  function chatMsgDomId(id, side) {
    return `chatmsg-${side}-${id}`;
  }

  function jumpToChatMsg(id, side) {
    if (id == null || !side) return;
    const key = chatMsgDomId(id, side);
    const el = document.getElementById(key);
    if (!el) return;
    el.scrollIntoView({ behavior: "smooth", block: "center" });
    setHighlightedMsgKey(key);
    clearTimeout(window.__tbvHighlightTimeout);
    window.__tbvHighlightTimeout = setTimeout(() => setHighlightedMsgKey(null), 1600);
  }

  function renderMsgContent(text) {
    if (!text) return null;
    const quoted = extractQuoteSnippet(text);
    const body = quoted !== null ? stripQuoteMarker(text) : text;
    const clickable = quoted && quoted.id != null;
    const quoteBlock = quoted ? (
      <div
        key="quote"
        onClick={clickable ? () => jumpToChatMsg(quoted.id, quoted.side) : undefined}
        className={`mb-1.5 flex items-start gap-1.5 rounded-lg border-l-[3px] border-sky-400/70 bg-sky-400/10 pl-2.5 pr-2 py-1.5 text-xs text-white/75 italic truncate max-w-full ${clickable ? "cursor-pointer hover:bg-sky-400/20 transition-colors" : ""}`}
      >
        <span className="not-italic font-bold text-sky-300 shrink-0">↩</span>
        <span className="truncate">{quoted.text}</span>
      </div>
    ) : null;
    return [quoteBlock, ...renderMsgBody(body)];
  }

  function renderMsgBody(text) {
    if (!text) return [];
    const parts = text.split(/(\[IMAGE:[^\]]+\]|\[FILE:[^\]]+\]|\[VIDEO:[^\]]+\])/g);
    return parts.map((part, i) => {
      const imgM = part.match(/^\[IMAGE:(.+)\]$/);
      if (imgM) {
        return (
          <img key={i} src={imgM[1]} alt="" className="mt-1.5 max-w-[240px] max-h-[200px] rounded-xl object-cover cursor-pointer block" onClick={() => setChatLightboxUrl(imgM[1])} />
        );
      }
      const videoM = part.match(/^\[VIDEO:(.+)\]$/);
      if (videoM) {
        return (
          <video key={i} src={videoM[1]} controls playsInline className="mt-1.5 max-w-[280px] rounded-xl block" style={{maxHeight: "200px"}} />
        );
      }
      const fileM = part.match(/^\[FILE:(.+):([^\]]*)\]$/);
      if (fileM) {
        const [, url, name] = fileM;
        return (
          <a key={i} href={url} target="_blank" rel="noopener noreferrer" className="mt-1.5 flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-sm text-white hover:bg-white/15 max-w-[240px]">
            <svg className="w-5 h-5 shrink-0 text-red-400" viewBox="0 0 24 24" fill="currentColor"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6zm-1 1.5L18.5 9H13V3.5zM8.5 17h7v1h-7v-1zm0-3h7v1h-7v-1zm0-3H11v1H8.5v-1z"/></svg>
            <span className="truncate text-xs">{name || "document.pdf"}</span>
          </a>
        );
      }
      return part ? <span key={i} className="whitespace-pre-wrap">{part}</span> : null;
    });
  }

  async function uploadAndSendImage(file, sendFn) {
    const isImage = file?.type.startsWith('image/');
    const isVideo = file?.type.startsWith('video/');
    const isPdf = file?.type === 'application/pdf' || file?.name?.toLowerCase().endsWith('.pdf');
    if (!file || (!isImage && !isVideo && !isPdf)) return;
    if (isVideo && file.size > 100 * 1024 * 1024) { alert('Video must be under 100 MB'); return; }
    setChatImageUploading(true);
    try {
      const ext = (file.name.split('.').pop() || (isPdf ? 'pdf' : isVideo ? 'mp4' : 'jpg')).toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 4) || 'bin';
      const path = `${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
      const { error } = await supabase.storage.from('chat-images').upload(path, file, { contentType: file.type, upsert: false });
      if (error) throw new Error(error.message);
      const { data: { publicUrl } } = supabase.storage.from('chat-images').getPublicUrl(path);
      await sendFn(publicUrl, file.name, isPdf, isVideo);
    } catch (err) {
      alert('Upload failed: ' + err.message);
    } finally {
      setChatImageUploading(false);
    }
  }

  async function sendImageAsUserMessage(url, fileName, isPdf, isVideo) {
    const name = contactForm.name.trim() || (currentUser?.email || "Anonymous");
    const email = (currentUser?.email || contactForm.email.trim() || "").toLowerCase();
    const tag = isVideo ? `[VIDEO:${url}]` : isPdf ? `[FILE:${url}:${fileName || 'document.pdf'}]` : `[IMAGE:${url}]`;
    const quotePrefix = replyPreview ? `[QUOTE:${encodeURIComponent(JSON.stringify(replyPreview))}]` : "";
    const message = quotePrefix + tag;
    const { error } = await supabase.from("contact_messages").insert({ name, email, message });
    setReplyPreview(null);
    if (error) { alert("Send failed: " + error.message); return; }
    const optimistic = { id: "opt-" + Date.now(), name, email, message, created_at: new Date().toISOString(), admin_reply: null };
    setUserInboxMessages((prev) => [...prev, optimistic]);
    loadUserInbox();
  }

  async function sendImageAsAdminMessage(url, toEmail, lastUnanswered, fileName, isPdf, isVideo) {
    const fileTag = isVideo ? `[VIDEO:${url}]` : isPdf ? `[FILE:${url}:${fileName || 'document.pdf'}]` : `[IMAGE:${url}]`;
    const quotePrefix = adminReplyPreview ? `[QUOTE:${encodeURIComponent(JSON.stringify(adminReplyPreview))}]` : "";
    const tag = quotePrefix + fileTag;
    try {
      if (lastUnanswered) {
        const { error } = await supabase.from("contact_messages").update({ admin_reply: tag, replied_at: new Date().toISOString() }).eq("id", lastUnanswered.id);
        if (error) throw new Error(error.message);
      } else {
        const { error } = await supabase.from("contact_messages").insert({ name: "Support", email: toEmail.trim().toLowerCase(), message: "[Admin initiated message]", admin_reply: tag, replied_at: new Date().toISOString(), user_read_at: null });
        if (error) throw new Error(error.message);
      }
      setAdminReplyPreview(null);
      loadAdminMessages();
    } catch (err) {
      alert('Send failed: ' + err.message);
    }
  }

  function setupTypingChannel(email) {
    if (typingChannelRef.current) {
      supabase.removeChannel(typingChannelRef.current);
      typingChannelRef.current = null;
    }
    if (!email) return;
    const amAdmin = ADMIN_EMAILS.includes(normalizeEmail(email) === normalizeEmail(currentUser?.email) ? '' : currentUser?.email || '');
    const ch = supabase.channel(`chat-typing:${email.toLowerCase()}`);
    ch.on('broadcast', { event: 'typing' }, ({ payload }) => {
      clearTimeout(typingStopTimerRef.current);
      if (ADMIN_EMAILS.includes(normalizeEmail(currentUser?.email)) && payload.role === 'user') {
        setUserIsTyping(true);
        typingStopTimerRef.current = setTimeout(() => setUserIsTyping(false), 3500);
      } else if (!ADMIN_EMAILS.includes(normalizeEmail(currentUser?.email)) && payload.role === 'admin') {
        setAdminIsTyping(true);
        typingStopTimerRef.current = setTimeout(() => setAdminIsTyping(false), 3500);
      }
    }).subscribe();
    typingChannelRef.current = ch;
  }

  function broadcastTyping(role) {
    if (!typingChannelRef.current) return;
    typingChannelRef.current.send({ type: 'broadcast', event: 'typing', payload: { role } });
  }

  async function sendContactMessage() {
    if (!contactForm.message.trim()) return;
    setContactSending(true);
    const name = contactForm.name.trim() || (currentUser?.email || "Anonymous");
    // Logged-in account email always wins — a stale/typed value in contactForm.email
    // (e.g. left over from a guest session) must never override the real account.
    const email = (currentUser?.email || contactForm.email.trim() || "").toLowerCase();
    const quotePrefix = replyPreview ? `[QUOTE:${encodeURIComponent(JSON.stringify(replyPreview))}]` : "";
    const message = quotePrefix + contactForm.message.trim();
    const { error } = await supabase.from("contact_messages").insert({ name, email, message });
    setContactSending(false);
    if (error) {
      alert("Send failed: " + error.message);
      return;
    }
    // Remember this email so guest users (not logged in) can still reload their own thread later
    if (email) { try { window.localStorage.setItem("tbv_guest_email", email); } catch {} }
    // Clear input and add optimistic message immediately
    setContactForm((f) => ({ ...f, message: "" }));
    setReplyPreview(null);
    const optimistic = { id: "opt-" + Date.now(), name, email, message, created_at: new Date().toISOString(), admin_reply: null };
    setUserInboxMessages((prev) => [...prev, optimistic]);
    // Then sync from server to get the real id
    loadUserInbox();
  }

