  async function loadUserInbox(silent = false) {
    // Logged-in users use their account email; guests fall back to whatever email
    // they last sent a message from (saved in localStorage), so their thread
    // survives a page reload / modal reopen instead of vanishing.
    let email = currentUser?.email || "";
    if (!email) {
      try { email = window.localStorage.getItem("tbv_guest_email") || ""; } catch {}
    }
    if (!email) return;
    email = email.toLowerCase();
    if (!silent) setUserInboxLoading(true);
    const { data } = await supabase
      .from("contact_messages")
      .select("*")
      .eq("email", email)
      .order("created_at", { ascending: true });
    const msgs = data || [];
    setUserInboxMessages(msgs);
    setHasUnreadReply(msgs.some(m => m.admin_reply && !m.user_read_at));
    setUserInboxLoading(false);
    loadReactions();
  }

  function getAffiliateCommissionBaseAmount(order) {
    return Number(order?.affiliateCommission || Number(order?.subtotal || 0) * 0.1);
  }

  function isCommissionEligibleOrder(order) {
    const status = String(order?.status || "").toLowerCase();
    return status === "paid" || status === "done";
  }

  function isOrderDone(order) {
    if (!isCommissionEligibleOrder(order)) return false;
    const status = String(order?.status || "").toLowerCase();
    return status === "done" || isAffiliateCommissionAvailable(order);
  }

  function getAffiliateCommissionAdjustment(order) {
    return Number(
      order?.affiliateCommissionAdjustment ||
        order?.affiliateCommissionDeduction ||
        order?.refundCommissionDeduction ||
        0
    );
  }

  function getAffiliateCommissionNetAmount(order) {
    return Math.max(0, getAffiliateCommissionBaseAmount(order) - getAffiliateCommissionAdjustment(order));
  }

  function getAffiliateReleaseDays(order) {
    // US warehouse: order.fromWarehouse, or shippingType contains "us-warehouse",
    // or ALL items have fromWarehouse === "us"
    const itemsAllUS = Array.isArray(order?.items) && order.items.length > 0 && order.items.every(i => i.fromWarehouse === "us");
    const isUS = order?.fromWarehouse === "us"
      || String(order?.shippingType || "").toLowerCase().includes("us-warehouse")
      || itemsAllUS;
    if (isUS) return 6;
    const isExpress = String(order?.shippingType || "").toLowerCase().includes("express");
    if (isExpress) return 10;
    return 15;
  }

  function getAffiliateAvailableAt(order) {
    const baseDate = order?.paidAt || order?.createdAt;
    if (!baseDate) return null;
    const date = new Date(baseDate);
    if (Number.isNaN(date.getTime())) return null;
    date.setDate(date.getDate() + getAffiliateReleaseDays(order));
    return date;
  }

  function isAffiliateCommissionAvailable(order) {
    const availableAt = getAffiliateAvailableAt(order);
    return availableAt ? Date.now() >= availableAt.getTime() : false;
  }

  async function loadStoreCredit(email) {
    if (!email) return;
    try {
      const { data } = await supabase
        .from("user_credits")
        .select("amount")
        .eq("email", email.toLowerCase().trim())
        .maybeSingle();
      setStoreCredit(data ? Number(data.amount ?? 0) : 0);
    } catch { /* ignore */ }
  }

  async function adminAddCredit(mode) {
    const email = adminCreditEmail.trim().toLowerCase();
    const amount = parseFloat(adminCreditAmount);
    if (!email || isNaN(amount)) { setAdminCreditMessage("Enter a valid email and amount."); return; }
    setAdminCreditLoading(true);
    setAdminCreditMessage("");
    try {
      const { data: existing } = await supabase.from("user_credits").select("amount").eq("email", email).maybeSingle();
      const currentAmount = existing ? Number(existing.amount) : 0;
      let newAmount;
      if (mode === "set") newAmount = amount;
      else if (mode === "subtract") newAmount = Math.max(0, currentAmount - Math.abs(amount));
      else newAmount = Math.max(0, currentAmount + amount);
      // UPDATE existing row first; INSERT if none exists (avoids duplicate rows from missing UNIQUE constraint)
      const { error: updErr, count } = await supabase.from("user_credits")
        .update({ amount: newAmount, note: adminCreditNote.trim() || null, updated_at: new Date().toISOString() })
        .eq("email", email);
      const needsInsert = !existing && !updErr;
      const { error } = needsInsert
        ? await supabase.from("user_credits").insert({ email, amount: newAmount, note: adminCreditNote.trim() || null, updated_at: new Date().toISOString() })
        : { error: updErr };
      // Clean up any duplicate rows
      const { data: dupRows } = await supabase.from("user_credits").select("id, updated_at").eq("email", email).order("updated_at", { ascending: false });
      if (dupRows && dupRows.length > 1) {
        await supabase.from("user_credits").delete().in("id", dupRows.slice(1).map(r => r.id));
      }
      if (error) { setAdminCreditMessage("Error: " + error.message); }
      else {
        setAdminCreditMessage(`✓ ${email} — new balance: $${newAmount.toFixed(2)}`);
        setAdminCreditLookup({ email, amount: newAmount });
        if (currentUser?.email?.toLowerCase() === email) setStoreCredit(newAmount);
      }
    } catch (e) { setAdminCreditMessage("Error: " + e.message); }
    setAdminCreditLoading(false);
  }

  async function adminLookupCredit() {
    const email = adminCreditEmail.trim().toLowerCase();
    if (!email) return;
    try {
      const { data } = await supabase.from("user_credits").select("amount, updated_at, note").eq("email", email).maybeSingle();
      setAdminCreditLookup(data ? { email, amount: Number(data.amount), updated_at: data.updated_at, note: data.note } : { email, amount: 0 });
    } catch { setAdminCreditLookup({ email, amount: 0 }); }
  }

  async function fetchUserPromos(email, currentAppliedPromo) {
    if (!email) return;
    try {
      const { data, error } = await supabase
        .from("user_promos")
        .select("*")
        .eq("email", String(email).trim().toLowerCase());
      if (!error && Array.isArray(data)) {
        const activePromos = data.filter((p) => !p.used);
        setUserPromos(activePromos);
        if (activePromos.length > 0 && !currentAppliedPromo) {
          const first = activePromos[0];
          setAppliedPromo({
            code: first.code,
            rate: first.rate,
            label: `${Math.round(first.rate * 100)}% discount`,
            type: "user_promo",
            id: first.id,
            issuedAt: first.created_at || "",
          });
        }
      }
    } catch (e) {
      console.error("Failed to fetch user promos:", e);
    }
  }

  async function issueUserPromo() {
    const email = issuePromoEmail.trim().toLowerCase();
    const code = issuePromoCode.trim().toUpperCase();
    const rate = parseFloat(issuePromoRate);
    if (!email || !code || !rate || rate <= 0 || rate > 100) {
      setIssuePromoMessage("Fill all fields correctly. Rate: 1–100.");
      return;
    }
    try {
      const rateDecimal = rate > 1 ? rate / 100 : rate;
      const { error } = await supabase.from("user_promos").insert({
        email,
        code,
        rate: rateDecimal,
        used: false,
      });
      if (error) {
        setIssuePromoMessage(`Error: ${error.message}`);
      } else {
        setIssuePromoMessage(`✓ Promo ${code} (${rate}%) issued to ${email}`);
        setIssuePromoEmail("");
        setIssuePromoCode("");
        setIssuePromoRate("");
        fetch("/api/send-promo-code-email", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email, code, rate: rateDecimal }),
        }).catch((e) => console.error("Failed to send promo code email:", e));
      }
    } catch (e) {
      setIssuePromoMessage(`Error: ${String(e)}`);
    }
    window.setTimeout(() => setIssuePromoMessage(""), 6000);
  }

  async function sendTrackingEmail({ email, orderId, trackingNumber, firstName }) {
    console.log("[sendTrackingEmail] called", { email, orderId, trackingNumber });
    try {
      const res = await fetch("/api/supabase/send-tracking-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, orderId, trackingNumber, firstName }),
      });
      const data = await res.json().catch(() => ({}));
      console.log("[sendTrackingEmail] response", res.status, data);
      if (res.ok) {
        setAdminMessage(`Tracking email sent to ${email}`);
        window.clearTimeout(window.__tbvAdminMessageTimeout);
        window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 4000);
      } else {
        setAdminMessage(`Tracking email failed: ${data?.error || res.status}`);
        window.clearTimeout(window.__tbvAdminMessageTimeout);
        window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 6000);
      }
    } catch (e) {
      console.error("[sendTrackingEmail] error:", e);
      setAdminMessage(`Tracking email error: ${e?.message}`);
      window.clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 6000);
    }
  }

  async function generateInvoicePDF(order) {
    if (!window.jspdf) {
      await new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: "mm", format: "a4" });
    const W = 210; const margin = 18;
    let y = 0;

    // ── Header bar ──────────────────────────────────────────────────────────
    doc.setFillColor(18, 18, 18);
    doc.rect(0, 0, W, 32, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(18);
    doc.setFont("helvetica", "bold");
    doc.text("10BottleValueCo", margin, 14);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(180, 180, 180);
    doc.text("10bottlevalue.co  ·  support@10bottlevalue.co", margin, 22);
    doc.setFontSize(8);
    doc.text("Research peptides — 10-vial kits", margin, 28);

    // Status badge
    const statusText = String(order.status || "paid").toUpperCase();
    doc.setFillColor(34, 197, 94);
    doc.roundedRect(W - margin - 24, 10, 24, 10, 2, 2, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(7);
    doc.setFont("helvetica", "bold");
    doc.text(statusText, W - margin - 12, 16.5, { align: "center" });

    y = 42;

    // ── Title ------------------------------------------------------------────
    doc.setTextColor(20, 20, 20);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("PAYMENT CONFIRMATION", margin, y);
    y += 6;
    doc.setDrawColor(230, 230, 230);
    doc.setLineWidth(0.3);
    doc.line(margin, y, W - margin, y);
    y += 7;

    // ── Order meta ───────────────────────────────────────────────────────────
    const paidDate = order.paidAt || order.createdAt || new Date().toISOString();
    const fmtDate = new Date(paidDate).toLocaleString("en-GB", { day: "2-digit", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" });

    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(80, 80, 80);
    doc.text("ORDER NUMBER", margin, y);
    doc.text("DATE", W / 2 + 5, y);
    y += 5;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(20, 20, 20);
    doc.text(String(order.invoiceId || order.id || "—"), margin, y);
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text(fmtDate, W / 2 + 5, y);

    if (order.paymentProvider && order.paymentProvider !== "pending") {
      y += 5;
      doc.setFontSize(8);
      doc.setTextColor(100, 100, 100);
      doc.text(`Payment method: ${order.paymentProvider}${order.paymentId ? "  ·  Ref: " + order.paymentId.slice(0, 28) : ""}`, margin, y);
    }
    y += 4;

    // ── Separator ------------------------------------------------------------
    doc.setDrawColor(230, 230, 230);
    doc.line(margin, y, W - margin, y);
    y += 7;

    // ── Customer info ────────────────────────────────────────────────────────
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(80, 80, 80);
    doc.text("BILL / SHIP TO", margin, y);
    doc.text("CONTACT", W / 2 + 5, y);
    y += 5;
    doc.setFont("helvetica", "normal");
    doc.setTextColor(20, 20, 20);
    doc.setFontSize(9.5);

    const name = [order.firstName, order.lastName].filter(Boolean).join(" ") || "—";
    doc.setFont("helvetica", "bold");
    doc.text(name, margin, y);
    doc.setFont("helvetica", "normal");
    doc.text(order.email || "—", W / 2 + 5, y);
    y += 5;
    if (order.address) { doc.text(order.address, margin, y); y += 5; }
    if (order.city || order.postalCode) { doc.text([order.city, order.postalCode].filter(Boolean).join(", "), margin, y); y += 5; }
    if (order.country) { doc.text(order.country, margin, y); }
    if (order.phone) { doc.text(`Tel: ${order.phone}`, W / 2 + 5, y); }
    y += 8;

    // ── Items table ──────────────────────────────────────────────────────────
    doc.setFillColor(30, 30, 30);
    doc.rect(margin, y, W - margin * 2, 7, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(8);
    doc.setFont("helvetica", "bold");
    doc.text("ITEM", margin + 3, y + 4.7);
    doc.text("QTY", W - margin - 42, y + 4.7, { align: "right" });
    doc.text("UNIT PRICE", W - margin - 22, y + 4.7, { align: "right" });
    doc.text("TOTAL", W - margin - 2, y + 4.7, { align: "right" });
    y += 7;

    doc.setTextColor(20, 20, 20);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    const items = Array.isArray(order.items) ? order.items : [];
    items.forEach((item, i) => {
      if (i % 2 === 0) { doc.setFillColor(248, 248, 248); doc.rect(margin, y, W - margin * 2, 6.5, "F"); }
      const qty = item.quantity ?? item.qty ?? 1;
      doc.text(`${item.name} ${item.dose || ""}`.trim(), margin + 3, y + 4.5);
      doc.text(String(qty), W - margin - 42, y + 4.5, { align: "right" });
      doc.text(`$${Number(item.price || 0).toFixed(2)}`, W - margin - 22, y + 4.5, { align: "right" });
      doc.text(`$${(Number(item.price || 0) * qty).toFixed(2)}`, W - margin - 2, y + 4.5, { align: "right" });
      y += 6.5;
    });
    doc.setDrawColor(220, 220, 220);
    doc.line(margin, y, W - margin, y);
    y += 6;

    // ── Price breakdown ───────────────────────────────────────────────────────
    const col1 = W - margin - 60; const col2 = W - margin - 2;
    const row = (label, value, bold = false, color = null) => {
      doc.setFontSize(9);
      doc.setFont("helvetica", bold ? "bold" : "normal");
      if (color) doc.setTextColor(...color); else doc.setTextColor(60, 60, 60);
      doc.text(label, col1, y, { align: "right" });
      if (color) doc.setTextColor(...color); else doc.setTextColor(20, 20, 20);
      doc.text(value, col2, y, { align: "right" });
      y += 5.5;
    };
    row("Subtotal:", `$${Number(order.subtotal || 0).toFixed(2)}`);
    row("Shipping:", Number(order.shipping) === 0 ? "FREE" : `+$${Number(order.shipping || 0).toFixed(2)}`);
    if (Number(order.automaticDiscount) > 0) row("Bulk discount:", `-$${Number(order.automaticDiscount).toFixed(2)}`, false, [34, 197, 94]);
    if (Number(order.promoDiscount) > 0) row(`Promo (${order.promoCode || ""}):`, `-$${Number(order.promoDiscount).toFixed(2)}`, false, [34, 197, 94]);
    if (Number(order.affiliateDiscount) > 0) row("Affiliate discount:", `-$${Number(order.affiliateDiscount).toFixed(2)}`, false, [34, 197, 94]);
    if (Number(order.storeCreditUsed) > 0) row("Store credits:", `-$${Number(order.storeCreditUsed).toFixed(2)}`, false, [6, 182, 212]);
    if (Number(order.paypalFee) > 0) row("Processing fee:", `+$${Number(order.paypalFee).toFixed(2)}`);

    // Total box
    doc.setFillColor(20, 20, 20);
    doc.rect(W - margin - 64, y - 1, 64, 9, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text("TOTAL PAID:", W - margin - 36, y + 5.5, { align: "right" });
    doc.text(`$${Number(order.total || 0).toFixed(2)}`, W - margin - 2, y + 5.5, { align: "right" });
    y += 16;

    // ── Footer ------------------------------------------------------------────
    doc.setDrawColor(220, 220, 220);
    doc.line(margin, y, W - margin, y);
    y += 5;
    doc.setFontSize(7.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(130, 130, 130);
    doc.text("This document confirms payment received by 10BottleValueCo.", margin, y);
    y += 4.5;
    doc.text("All products are for laboratory research use only. Not for human or animal use.", margin, y);
    y += 4.5;
    doc.text(`Shipping method: ${order.shippingType || "standard"}`, margin, y);
    if (order.trackingNumber) { doc.text(`Tracking: ${order.trackingNumber}`, margin + 75, y); }

    doc.save(`Invoice_${order.id || "order"}.pdf`);
  }

  function updateOrderAdminField(orderId, field, value) {
    const orders = getStoredOrders();
    let supabasePayload = null;
    let trackingEmailData = null;
    let adminNoteValue = null;
    const nextOrders = orders.map((order) => {
      if (order.id !== orderId) return order;
      if (field === "status") {
        const nextStatus = String(value || "pending").toLowerCase();
        const nextPaidAt = ["paid", "done"].includes(nextStatus)
          ? order.paidAt || new Date().toISOString()
          : order.paidAt || "";
        supabasePayload = { status: nextStatus };
        return {
          ...order,
          status: nextStatus,
          paidAt: nextPaidAt,
        };
      }
      const nextValue = field === "affiliateCommissionAdjustment" ? Number(value || 0) : value;
      if (field === "affiliateCommissionAdjustment") {
        supabasePayload = { affiliate_commission_adjustment: nextValue };
      }
      if (field === "trackingNumber") {
        const trimmed = String(value || "").trim();
        const sentAt = trimmed ? new Date().toISOString() : order.trackingNumberSentAt || "";
        supabasePayload = { tracking_number: trimmed, tracking_number_sent_at: sentAt };
        if (trimmed && order.email) {
          trackingEmailData = {
            email: order.email,
            orderId: order.id,
            trackingNumber: trimmed,
            firstName: order.firstName || "",
          };
        }
        return {
          ...order,
          trackingNumber: trimmed,
          trackingNumberSentAt: sentAt,
        };
      }
      if (field === "trackingNumber2") {
        const trimmed = String(value || "").trim();
        supabasePayload = { tracking_number_2: trimmed };
        if (trimmed && order.email) {
          trackingEmailData = {
            email: order.email,
            orderId: order.id,
            trackingNumber: trimmed,
            firstName: order.firstName || "",
          };
        }
        return { ...order, trackingNumber2: trimmed };
      }
      if (["firstName", "lastName", "address", "city", "postalCode", "state", "country", "phone", "taxId"].includes(field)) {
        const trimmed = String(value || "").trim();
        supabasePayload = { [field]: trimmed };
        return { ...order, [field]: trimmed };
      }
      if (field === "createdAt") {
        const iso = value ? new Date(value).toISOString() : order.createdAt || "";
        supabasePayload = { created_at: iso };
        return { ...order, createdAt: iso };
      }
      if (field === "invoiceId") {
        const trimmed = String(value || "").trim();
        supabasePayload = { invoice_id: trimmed };
        return { ...order, invoiceId: trimmed };
      }
      if (field === "paymentProvider") {
        const trimmed = String(value || "").trim();
        supabasePayload = { payment_provider: trimmed };
        return { ...order, paymentProvider: trimmed };
      }
      if (field === "paymentId") {
        const trimmed = String(value || "").trim();
        supabasePayload = { payment_id: trimmed };
        return { ...order, paymentId: trimmed };
      }
      if (field === "subtotal") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { subtotal: num };
        return { ...order, subtotal: num };
      }
      if (field === "shipping") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { shipping: num };
        return { ...order, shipping: num };
      }
      if (field === "storeCreditUsed") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { store_credit_used: num };
        return { ...order, storeCreditUsed: num };
      }
      if (field === "total") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { total: num };
        return { ...order, total: num };
      }
      if (field === "shippingType") {
        const trimmed = String(value || "standard").trim();
        supabasePayload = { shipping_type: trimmed };
        return { ...order, shippingType: trimmed };
      }
      if (field === "adminNote") {
        const trimmed = String(value || "").trim();
        adminNoteValue = trimmed; // handled separately — never touches a DB column
        return { ...order, adminNote: trimmed };
      }
      return {
        ...order,
        [field]: nextValue,
      };
    });
    saveStoredOrders(nextOrders);
    if (currentUser?.email) setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
    setAdminMessage("Admin update saved.");
    window.clearTimeout(window.__tbvAdminMessageTimeout);
    window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 2500);

    if (supabasePayload) {
      persistOrderAdminFieldToSupabase(orderId, supabasePayload);
    }
    if (adminNoteValue !== null) {
      // Write admin note directly to metadata — avoids any DB column lookup
      (async () => {
        try {
          if (!String(orderId).startsWith("TEST-")) {
            const { data, error: readErr } = await supabase.from("orders").select("metadata").eq("id", orderId).single();
            if (readErr) throw new Error(readErr.message);
            const base = typeof data?.metadata === "object" && !Array.isArray(data.metadata) ? data.metadata : {};
            const { error: writeErr } = await supabase.from("orders").update({ metadata: { ...base, adminNote: adminNoteValue } }).eq("id", orderId);
            if (writeErr) throw new Error(writeErr.message);
          }
        } catch (err) {
          console.error("Failed to persist admin note:", err?.message || err);
        }
      })();
    }
    if (trackingEmailData) {
      sendTrackingEmail(trackingEmailData);
    }
  }

  async function deleteOrdersByEmail(email) {
    const target = String(email || "").trim().toLowerCase();
    if (!target) return;
    const matches = allOrders.filter((o) => String(o.email || "").trim().toLowerCase() === target);
    if (matches.length === 0) {
      window.alert(`No orders found for ${email}.`);
      return;
    }
    if (!window.confirm(`Delete all ${matches.length} order(s) placed with ${email}? This cannot be undone.`)) return;
    const ids = matches.map((o) => o.id);
    try {
      await supabase.from("orders").delete().in("id", ids);
    } catch (e) {
      console.error("Bulk delete orders error:", e);
    }
    try {
      await supabase.from("affiliate_orders").delete().in("order_id", ids);
    } catch (e) {
      console.error("Bulk delete affiliate_orders error:", e);
    }
    const deletedIds = new Set(JSON.parse(localStorage.getItem("tbv-deleted-order-ids") || "[]"));
    ids.forEach((id) => deletedIds.add(id));
    localStorage.setItem("tbv-deleted-order-ids", JSON.stringify([...deletedIds]));
    const next = getStoredOrders().filter((o) => !ids.includes(o.id));
    localStorage.setItem("tbv-orders", JSON.stringify(next));
    setAllOrders((prev) => prev.filter((o) => !ids.includes(o.id)));
    await loadOrdersFromSupabase();
  }

  async function deleteAdminOrder(orderId) {
    if (!window.confirm("Delete this order permanently? This cannot be undone.")) return;
    try {
      await supabase.from("orders").delete().eq("id", orderId);
    } catch (e) {
      console.error("Delete order error:", e);
    }
    // Also remove affiliate commission record so affiliate panel stays in sync
    try {
      await supabase.from("affiliate_orders").delete().eq("order_id", orderId);
    } catch (e) {
      console.error("Delete affiliate_orders error:", e);
    }
    // Persist deleted ID so it stays hidden even after Supabase reload
    const deletedIds = JSON.parse(localStorage.getItem("tbv-deleted-order-ids") || "[]");
    if (!deletedIds.includes(orderId)) deletedIds.push(orderId);
    localStorage.setItem("tbv-deleted-order-ids", JSON.stringify(deletedIds));
    const next = getStoredOrders().filter((o) => o.id !== orderId);
    localStorage.setItem("tbv-orders", JSON.stringify(next));
    setAllOrders(next);
  }

  async function updateOrderItemsAdmin(orderId, newItems) {
    const orders = getStoredOrders();
    const existingOrder = orders.find((o) => o.id === orderId);
    const shipping = Number(existingOrder?.shipping || 0);
    const storeCreditUsed = Number(existingOrder?.storeCreditUsed || 0);
    const newSubtotal = newItems.reduce((sum, item) => sum + (Number(item.price || 0) * Number(item.quantity || item.qty || 1)), 0);
    const newTotal = Math.max(0, newSubtotal + shipping - storeCreditUsed);
    const nextOrders = orders.map((o) => o.id !== orderId ? o : { ...o, items: newItems, subtotal: newSubtotal, total: newTotal });
    saveStoredOrders(nextOrders);
    if (currentUser?.email) setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
    setAdminMessage("Items updated.");
    window.clearTimeout(window.__tbvAdminMessageTimeout);
    window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 2000);
    if (String(orderId).startsWith("TEST-")) return;
    try {
      const { data, error: readErr } = await supabase.from("orders").select("metadata").eq("id", orderId).single();
      if (readErr) throw new Error(readErr.message);
      const baseMeta = typeof data?.metadata === "object" && !Array.isArray(data.metadata) ? data.metadata : {};
      const { error: writeErr } = await supabase.from("orders").update({
        metadata: { ...baseMeta, items: newItems, subtotal: newSubtotal, total: newTotal },
        total: newTotal,
      }).eq("id", orderId);
      if (writeErr) throw new Error(writeErr.message);
    } catch (err) {
      console.error("Failed to update order items in Supabase:", err?.message || err);
      setAdminMessage(`Sync failed: ${err?.message || "unknown error"}`);
      window.clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 5000);
    }
  }


  function createTestOrder() {
    const testId = "TEST-" + Date.now().toString().slice(-6);
    const testOrder = {
      id: testId,
      email: currentUser?.email || "test@example.com",
      status: "paid",
      paymentProvider: "test",
      paymentId: "test-payment-" + testId,
      paidAt: new Date().toISOString(),
      confirmationEmailSentAt: "",
      createdAt: new Date().toISOString(),
      shippingType: "standard",
      firstName: "Test",
      lastName: "User",
      country: "US",
      address: "123 Test Street",
      city: "Test City",
      postalCode: "10001",
      phone: "+1 555 0100",
      taxId: "",
      orderNotes: "This is a test order created from the admin panel.",
      trackingNumber: "",
      subtotal: 990,
      shipping: 0,
      automaticDiscount: 0,
      promoDiscount: 0,
      affiliateDiscount: 0,
      total: 990,
      affiliateCode: "",
      affiliateOwnerEmail: "",
      affiliateCommission: 0,
      items: [
        { name: "BPC-157", dose: "5mg", quantity: 10, price: 99 },
      ],
    };
    const orders = getStoredOrders();
    const nextOrders = [testOrder, ...orders];
    saveStoredOrders(nextOrders);
    if (currentUser?.email) setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
    setAdminMessage(`Test order ${testId} created.`);
    window.clearTimeout(window.__tbvAdminMessageTimeout);
    window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 3000);
  }

  async function persistOrderAdminFieldToSupabase(orderId, payload) {
    // Test orders only exist locally — skip Supabase sync silently
    if (String(orderId).startsWith("TEST-")) return;
    try {
      // Fields stored inside metadata JSONB (no direct columns for them)
      const METADATA_FIELDS = { tracking_number: "trackingNumber", tracking_number_2: "trackingNumber2", order_notes: "orderNotes", tracking_number_sent_at: "trackingNumberSentAt", firstName: "firstName", lastName: "lastName", address: "address", address2: "address2", city: "city", postalCode: "postalCode", state: "state", country: "country", phone: "phone", taxId: "taxId", admin_note: "adminNote", store_credit_used: "storeCreditUsed", subtotal: "subtotal", shipping: "shipping", invoice_id: "invoiceId", shipping_type: "shippingType" };
      const metaUpdates = {};
      const directUpdates = {};
      for (const [k, v] of Object.entries(payload)) {
        if (k in METADATA_FIELDS) metaUpdates[METADATA_FIELDS[k]] = v;
        else directUpdates[k] = v;
      }
      if (Object.keys(directUpdates).length > 0) {
        const { error } = await supabase.from("orders").update(directUpdates).eq("id", orderId);
        if (error) throw new Error(error.message);
      }
      const needsMetaRead = Object.keys(metaUpdates).length > 0 || "status" in directUpdates;
      if (needsMetaRead) {
        const { data, error: readErr } = await supabase.from("orders").select("metadata").eq("id", orderId).single();
        if (readErr) throw new Error(readErr.message);
        const baseMeta = typeof data?.metadata === "object" && !Array.isArray(data.metadata) ? data.metadata : {};
        const statusMeta = "status" in directUpdates ? { status: directUpdates.status } : {};
        const merged = { ...baseMeta, ...metaUpdates, ...statusMeta };
        const { error: writeErr } = await supabase.from("orders").update({ metadata: merged }).eq("id", orderId);
        if (writeErr) throw new Error(writeErr.message);
      }
    } catch (err) {
      console.error("Failed to persist admin order edit to Supabase:", err?.message || err);
      setAdminMessage(`Sync failed: ${err?.message || "unknown error"}`);
      window.clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 5000);
    }
  }

  function getStoredOrders() {
    try {
      const parsed = JSON.parse(localStorage.getItem("tbv-orders") || "[]");
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  function saveStoredOrders(nextOrders) {
    localStorage.setItem("tbv-orders", JSON.stringify(nextOrders));
    setAllOrders(nextOrders);
  }

  function getPaidOrdersForEmail(email, orders = getStoredOrders()) {
    const normalizedEmail = normalizeEmail(email);
    if (!normalizedEmail) return [];

    return orders.filter(
      (order) =>
        normalizeEmail(order.email) === normalizedEmail &&
        String(order.status || "pending").toLowerCase() === "paid"
    );
  }

  function syncUserPaidOrders(email = currentUser?.email) {
    const orders = getStoredOrders();
    setAllOrders(orders);
    setUserOrders(getPaidOrdersForEmail(email, orders));
    return orders;
  }

  const [isRefreshingUserOrders, setIsRefreshingUserOrders] = useState(false);
  const [authReady, setAuthReady] = useState(false);

  async function refreshUserOrdersFromSupabase(email = currentUser?.email) {
    if (!email) { console.log("[TBV] refreshOrders: no email, skipping"); return; }
    console.log("[TBV] refreshOrders: start for", email);
    setIsRefreshingUserOrders(true);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      console.log("[TBV] refreshOrders: session user=", session?.user?.email || "none");
      const { data, error } = await supabase
        .from("orders")
        .select("*")
        .eq("email", normalizeEmail(email))
        .order("created_at", { ascending: false });
      console.log("[TBV] refreshOrders: result rows=", data?.length, "error=", error?.message);
      if (error) throw new Error(error.message);
      const rows = Array.isArray(data) ? data : [];
      const reconstructed = rows.map((sbOrder) => {
        const meta =
          sbOrder.metadata && typeof sbOrder.metadata === "object" && !Array.isArray(sbOrder.metadata)
            ? sbOrder.metadata
            : null;
        if (meta) {
          // See loadOrdersFromSupabase for why we merge fromWarehouse from the
          // structured `items` column into metadata.items.
          const metaItems = Array.isArray(meta.items) ? meta.items : [];
          const columnItems = Array.isArray(sbOrder.items) ? sbOrder.items : [];
          const mergedItems = metaItems.length > 0
            ? metaItems.map((item) => {
                if (item.fromWarehouse) return item;
                const match = columnItems.find((ci) => ci.name === item.name && ci.dose === item.dose);
                return match?.fromWarehouse ? { ...item, fromWarehouse: match.fromWarehouse } : item;
              })
            : columnItems;
          return {
            ...meta,
            items: mergedItems,
            id: sbOrder.id ?? meta.id,
            invoiceId: meta.invoiceId || "",
            email: meta.email || sbOrder.email || "",
            total: meta.total ?? sbOrder.total ?? 0,
            status: sbOrder.status ?? meta.status ?? "pending",
            createdAt: meta.createdAt || sbOrder.created_at || "",
            paymentProvider: sbOrder.payment_provider || meta.paymentProvider || "",
            paymentId: sbOrder.payment_id || meta.paymentId || "",
            affiliateCommissionAdjustment:
              sbOrder.affiliate_commission_adjustment ?? meta.affiliateCommissionAdjustment ?? 0,
          };
        }
        return {
          id: sbOrder.id,
          invoiceId: "",
          email: sbOrder.email || "",
          total: sbOrder.total ?? 0,
          status: sbOrder.status || "pending",
          createdAt: sbOrder.created_at || "",
          items: sbOrder.items || [],
          shipping: sbOrder.shipping ?? 0,
          shippingType: sbOrder.shipping_type || "standard",
        };
      });

      const existingOrders = getStoredOrders();
      const existingMap = new Map(existingOrders.map((o) => [o.id, o]));
      for (const order of reconstructed) {
        const existing = existingMap.get(order.id) || {};
        const existingItems = Array.isArray(existing.items) && existing.items.length > 0 ? existing.items : null;
        const newItems = Array.isArray(order.items) && order.items.length > 0 ? order.items : null;
        existingMap.set(order.id, { ...existing, ...order, items: newItems || existingItems || [] });
      }
      const merged = Array.from(existingMap.values()).sort(
        (a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime()
      );
      localStorage.setItem("tbv-orders", JSON.stringify(merged));
      setAllOrders(merged);
      setUserOrders(getPaidOrdersForEmail(email, merged));
    } catch (err) {
      console.error("Failed to refresh user orders:", err);
    } finally {
      setIsRefreshingUserOrders(false);
    }
  }

  async function loadOrdersFromSupabase() {
    setIsLoadingOrders(true);
    try {
      // Paginate through all orders (Supabase server caps at 1000 per request)
      const PAGE = 1000;
      let allFetched = [];
      let from = 0;
      while (true) {
        const { data: batch, error: batchErr } = await supabase
          .from("orders")
          .select("*")
          .order("created_at", { ascending: false })
          .range(from, from + PAGE - 1);
        if (batchErr) throw new Error(batchErr.message);
        const rows = Array.isArray(batch) ? batch : [];
        allFetched = allFetched.concat(rows);
        if (rows.length < PAGE) break;
        from += PAGE;
      }
      const supabaseOrders = allFetched;

      // Filter out orders permanently deleted by admin
      const deletedIds = new Set(JSON.parse(localStorage.getItem("tbv-deleted-order-ids") || "[]"));
      const filteredSupabaseOrders = supabaseOrders.filter((o) => !deletedIds.has(o.id));

      const reconstructed = filteredSupabaseOrders.map((sbOrder) => {
        const meta =
          sbOrder.metadata && typeof sbOrder.metadata === "object" && !Array.isArray(sbOrder.metadata)
            ? sbOrder.metadata
            : null;

        if (meta) {
          // metadata.items sometimes omits fields like `fromWarehouse` that were
          // only persisted onto the structured `items` column server-side.
          // Merge fromWarehouse in by matching name+dose so the US Warehouse
          // badge/logic still works even when metadata.items is the source of truth.
          const metaItems = Array.isArray(meta.items) ? meta.items : [];
          const columnItems = Array.isArray(sbOrder.items) ? sbOrder.items : [];
          const mergedItems = metaItems.length > 0
            ? metaItems.map((item) => {
                if (item.fromWarehouse) return item;
                const match = columnItems.find((ci) => ci.name === item.name && ci.dose === item.dose);
                return match?.fromWarehouse ? { ...item, fromWarehouse: match.fromWarehouse } : item;
              })
            : columnItems;

          // The full order object lives in `metadata`. Structured columns
          // that admins edit directly (status, affiliate_commission_adjustment)
          // override the metadata snapshot so admin edits are reflected.
          return {
            ...meta,
            items: mergedItems,
            id: sbOrder.id ?? meta.id,
            invoiceId: meta.invoiceId || "",
            email: meta.email || sbOrder.email || "",
            total: meta.total ?? sbOrder.total ?? 0,
            status: sbOrder.status ?? meta.status ?? "pending",
            createdAt: meta.createdAt || sbOrder.created_at || "",
            paymentProvider: sbOrder.payment_provider || meta.paymentProvider || "",
            paymentId: sbOrder.payment_id || meta.paymentId || "",
            affiliateCommissionAdjustment:
              sbOrder.affiliate_commission_adjustment ??
              meta.affiliateCommissionAdjustment ??
              0,
          };
        }

        // Legacy orders saved before the metadata column existed: rebuild
        // from whatever structured columns the table happens to expose.
        return {
          id: sbOrder.id,
          email: sbOrder.email || "",
          total: sbOrder.total ?? 0,
          subtotal: sbOrder.subtotal ?? sbOrder.total ?? 0,
          status: sbOrder.status || "pending",
          createdAt: sbOrder.created_at || "",
          paidAt: sbOrder.paid_at || "",
          paymentProvider: sbOrder.payment_provider || "",
          paymentId: sbOrder.payment_id || "",
          affiliateCode: sbOrder.affiliate_code || "",
          affiliateOwnerEmail: sbOrder.affiliate_owner_email || "",
          affiliateCommissionAdjustment: sbOrder.affiliate_commission_adjustment ?? 0,
          items: sbOrder.items || [],
          shipping: sbOrder.shipping ?? 0,
          shippingType: sbOrder.shipping_type || "standard",
          automaticDiscount: sbOrder.automatic_discount ?? 0,
          promoDiscount: sbOrder.promo_discount ?? 0,
          affiliateDiscount: sbOrder.affiliate_discount ?? 0,
        };
      });

      const cutoff = Date.now() - 24 * 60 * 60 * 1000;
      const localTestOrders = getStoredOrders().filter(
        (o) =>
          String(o.id).startsWith("TEST-") &&
          new Date(o.createdAt || 0).getTime() > cutoff
      );
      const supabaseIds = new Set(reconstructed.map((o) => o.id));
      const freshTestOrders = localTestOrders.filter((o) => !supabaseIds.has(o.id));
      const withTest = [...freshTestOrders, ...reconstructed];

      withTest.sort((a, b) => {
        const da = new Date(a.createdAt || a.created_at || 0).getTime();
        const db = new Date(b.createdAt || b.created_at || 0).getTime();
        return db - da;
      });

      // Retroactive affiliate fix: for paid orders that have an affiliateCode but no
      // affiliateOwnerEmail stored, look up the owner from the affiliates table and
      // patch both the orders row and affiliate_orders. Fire-and-forget, best effort.
      (async () => {
        try {
          const needsFix = withTest.filter(
            (o) =>
              o.affiliateCode &&
              !o.affiliateOwnerEmail &&
              ["paid", "done"].includes(String(o.status || "").toLowerCase())
          );
          if (needsFix.length === 0) return;

          const codes = [...new Set(needsFix.map((o) => String(o.affiliateCode).trim().toUpperCase()))];
          const { data: affRows } = await supabase
            .from("affiliates")
            .select("code,email")
            .in("code", codes);

          if (!Array.isArray(affRows) || affRows.length === 0) return;
          const codeToEmail = Object.fromEntries(
            affRows.map((r) => [String(r.code).trim().toUpperCase(), String(r.email).trim().toLowerCase()])
          );

          for (const o of needsFix) {
            const code = String(o.affiliateCode).trim().toUpperCase();
            const ownerEmail = codeToEmail[code];
            if (!ownerEmail) continue;

            // Patch in-memory order
            o.affiliateOwnerEmail = ownerEmail;

            // Patch Supabase orders row
            const metaPatch = o.metadata && typeof o.metadata === "object"
              ? { ...o.metadata, affiliateOwnerEmail: ownerEmail }
              : undefined;
            const upsertPayload = {
              id: o.id,
              affiliate_owner_email: ownerEmail,
              ...(metaPatch ? { metadata: metaPatch } : {}),
            };
            supabase.from("orders").upsert(upsertPayload).then(() => {});

            // Ensure affiliate_orders row exists
            supabase.from("affiliate_orders").upsert({
              order_id: o.id,
              affiliate_code: code,
              commission_amount: Number(o.affiliateCommission) || Number(o.subtotal || o.total || 0) * 0.1,
              shipping_type: String(o.shippingType || "standard").toLowerCase(),
            }, { onConflict: "order_id" }).then(() => {});
          }
        } catch (e) {
          console.error("Retroactive affiliate fix failed:", e);
        }
      })();

      localStorage.setItem("tbv-orders", JSON.stringify(withTest));
      setAllOrders(withTest);
      if (currentUser?.email) {
        setUserOrders(getPaidOrdersForEmail(currentUser.email, withTest));
      }

      // Self-healing safety net: the NOWPayments IPN webhook occasionally fails to
      // flip an order to "paid" in Supabase even though the payment itself is
      // genuinely confirmed (confirmation email already sent) — root cause not
      // fully pinned down yet, so instead of relying solely on the webhook, every
      // time the admin panel loads orders we re-check any order still stuck in
      // "checkout (clicked pay)" directly against NOWPayments' own API and let the
      // server apply the same paid-order logic if it's actually confirmed. Cheap
      // no-op for non-crypto orders (NOWPayments simply reports no match).
      (async () => {
        try {
          const now = Date.now();
          const stuck = withTest.filter((o) => {
            const status = String(o.status || "").toLowerCase();
            if (status !== "checkout (clicked pay)" && status !== "checkout") return false;
            const age = now - new Date(o.createdAt || o.created_at || 0).getTime();
            return age > 2 * 60 * 1000 && age < 7 * 24 * 60 * 60 * 1000;
          });
          for (const o of stuck) {
            fetch("/api/verify-nowpayments-payment", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ order_id: o.id, payment_id: o.paymentId || undefined }),
            })
              .then((r) => r.json())
              .then((result) => {
                if (result?.dbMarkedPaid || result?.alreadyPaidInDb) loadOrdersFromSupabase();
              })
              .catch(() => {});
          }
        } catch (e) {
          console.error("Stuck-order reconciliation failed:", e);
        }
      })();
    } catch (error) {
      console.error("Failed to load orders from Supabase, falling back to localStorage", error);
      const localOrders = getStoredOrders();
      setAllOrders(localOrders);
    } finally {
      setIsLoadingOrders(false);
    }
  }

  async function sendPaymentConfirmedEmail(order) {
    if (!order?.email || order?.confirmationEmailSentAt) return;
    // Stripe, NOWPayments (crypto) and Paylio all have server-side webhooks
    // (api/stripe-webhook.js, api/_nowpayments-shared.js, api/paylio-callback.js)
    // that already send the confirmation email themselves, using the
    // authoritative Supabase order record (correct discounts/store credit/total).
    // Sending it again from here used a stale localStorage-cached `order` object
    // (built before the crypto discount/store-credit fields were fully known),
    // which caused a second email with a wrong, undiscounted total for crypto
    // orders. Only providers without their own webhook (PayPal, wire transfer)
    // still need this client-side send.
    const provider = String(order.paymentProvider || "").toLowerCase();
    const hasServerWebhookEmail =
      provider === "stripe" ||
      provider === "paylio" ||
      provider.includes("nowpayments") ||
      provider.includes("catalystpay") ||
      provider.includes("cashapp") ||
      provider.includes("crypto") ||
      provider.includes("usdt") ||
      provider.includes("usdc") ||
      provider.includes("btc") ||
      provider.includes("eth") ||
      provider.includes("·");
    if (hasServerWebhookEmail) return;

    try {
      const res = await fetch("/api/send-payment-confirmed-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          orderId: order.id,
          email: order.email,
          total: order.total,
          subtotal: order.subtotal || 0,
          shipping: order.shipping || 0,
          automaticDiscount: order.automaticDiscount || 0,
          promoDiscount: order.promoDiscount || 0,
          affiliateDiscount: order.affiliateDiscount || 0,
          affiliateCode: order.affiliateCode || "",
          affiliateOwnerEmail: order.affiliateOwnerEmail || "",
          affiliateCommission: order.affiliateCommission || 0,
          shippingType: order.shippingType,
          items: order.items || [],
          paymentProvider: order.paymentProvider || "Crypto",
          paymentId: order.paymentId || "",
          firstName: order.firstName || "",
          lastName: order.lastName || "",
          address: order.address || "",
          address2: order.address2 || "",
          city: order.city || "",
          state: order.state || "",
          postalCode: order.postalCode || "",
          phone: order.phone || "",
          country: order.country || "",
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data?.error || data?.message || "Payment confirmation email failed");
      }

      const orders = getStoredOrders();
      const nextOrders = orders.map((savedOrder) =>
        savedOrder.id === order.id
          ? { ...savedOrder, confirmationEmailSentAt: new Date().toISOString() }
          : savedOrder
      );
      saveStoredOrders(nextOrders);
      if (currentUser?.email) {
        setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
      }
    } catch (error) {
      console.error("Failed to send payment confirmation email", error);
    }
  }

  async function markOrderCheckoutStartedById(orderId, paymentProvider = "Paylio") {
    if (!orderId) return;
    const orders = getStoredOrders();
    let updatedOrder = null;
    const nextOrders = orders.map((savedOrder) => {
      if (savedOrder.id !== orderId) return savedOrder;
      const currentStatus = String(savedOrder.status || "").toLowerCase();
      if (currentStatus === "paid" || currentStatus === "done" || currentStatus === "refunded") {
        return savedOrder;
      }
      const next = {
        ...savedOrder,
        status: "checkout",
        paymentProvider: savedOrder.paymentProvider && savedOrder.paymentProvider !== "pending" ? savedOrder.paymentProvider : paymentProvider,
        checkoutStartedAt: savedOrder.checkoutStartedAt || new Date().toISOString(),
      };
      updatedOrder = next;
      return next;
    });
    saveStoredOrders(nextOrders);
    setAllOrders(nextOrders);
    if (updatedOrder) {
      try {
        const { error } = await supabase
          .from("orders")
          .upsert({
            id: updatedOrder.id,
            email: updatedOrder.email,
            status: "checkout",
            total: updatedOrder.total ?? 0,
            metadata: { ...updatedOrder, status: "checkout" },
          });
        if (error) console.error("Supabase: checkout upsert failed:", error.message);
      } catch (e) {
        console.error("Supabase: checkout upsert threw:", e);
      }
    }
  }

  function markOrderPaidById(orderId, paymentProvider = "NOWPayments", paymentId = "") {
    if (!orderId) return [];

    const orders = getStoredOrders();
    let paidOrder = null;
    let wasAlreadyPaid = false;
    const nextOrders = orders.map((savedOrder) => {
      if (savedOrder.id !== orderId) return savedOrder;

      wasAlreadyPaid = String(savedOrder.status || "").toLowerCase() === "paid";
      const updatedOrder = {
        ...savedOrder,
        status: "paid",
        paymentProvider,
        paymentId: paymentId || savedOrder.paymentId || "",
        paidAt: savedOrder.paidAt || new Date().toISOString(),
      };
      paidOrder = updatedOrder;
      return updatedOrder;
    });

    saveStoredOrders(nextOrders);

    if (paidOrder && !wasAlreadyPaid) {
      const paidAt = paidOrder.paidAt || new Date().toISOString();
      // Status in Supabase is set ONLY by server-side webhooks (Stripe / Paylio / NOWPayments).
      // The frontend must not write status:"paid" — it creates false positives when the
      // payment provider redirects to the success URL before the payment is confirmed.

      if (paidOrder.affiliateCode) {
        supabase
          .from("affiliate_orders")
          .upsert({
            order_id: paidOrder.id,
            affiliate_code: String(paidOrder.affiliateCode).trim().toUpperCase(),
            commission_amount: Number(paidOrder.affiliateCommission) || Number(paidOrder.subtotal || paidOrder.total || 0) * 0.1,
            shipping_type: String(paidOrder.shippingType || "standard").toLowerCase(),
          })
          .then(({ error }) => { if (error) console.error("Supabase: insert affiliate_orders failed:", error.message); });
      }

      // Store credit is now deducted server-side by the payment webhooks
      // (Stripe / CatalystPay / NOWPayments / Paylio), right when they mark
      // the order paid — this is the authoritative, always-runs-once path.
      // The frontend must NOT also deduct it here: doing so from a
      // read-then-write on the client, in addition to the same pattern
      // running server-side, could double-deduct the same order's credit
      // if both happened to run (e.g. a slow client poll racing the
      // webhook). The caller already refreshes the displayed balance via
      // loadStoreCredit(creditEmail) right after this function returns.
    }

    if (paidOrder && !wasAlreadyPaid) {
      if (appliedPromo?.type === "general") {
        setUsedPromoCodes((current) => [...current, appliedPromo.code]);
        setAppliedPromo(null);
      }
      if (appliedPromo?.type === "user_promo" && appliedPromo?.id) {
        const promoId = appliedPromo.id;
        const promoCode = appliedPromo.code;
        setUsedPromoCodes((current) => [...current, promoCode]);
        setUserPromos((current) => current.filter((p) => p.id !== promoId));
        supabase
          .from("user_promos")
          .update({ used: true })
          .eq("id", promoId)
          .then(({ error }) => { if (error) console.error("Failed to mark user promo as used:", error.message); });
      }
      setOwnerFreeShippingActive(false);
      setPromoInput("");
    }

    if (paidOrder && !paidOrder.confirmationEmailSentAt) {
      sendPaymentConfirmedEmail(paidOrder);
    }

    // Fallback DB update removed — only server-side webhooks may set status:"paid".

    return nextOrders;
  }

  useEffect(() => {
    if (typeof window === "undefined") return;

    const params = new URLSearchParams(window.location.search || "");
    const payment = (params.get("payment") || "").toLowerCase().trim();
    const order = (params.get("order") || "").trim();
    const npId = (params.get("NP_id") || params.get("payment_id") || "").trim();

    if (["success", "cancelled", "cancel", "failed"].includes(payment)) {
      const urlProvider = (params.get("provider") || "").toLowerCase().trim();
      const isCatalystPay = urlProvider === "catalystpay";

      // CatalystPay always redirects to ?payment=success even on cancel.
      // useState already initialised status="cancelled" so there is zero
      // flash of ORDER CONFIRMED. "Payment Cancelled" shows immediately.
      //
      // In the background we silently poll Supabase for up to ~60s so that
      // a real payment (where the webhook arrives slightly after the redirect)
      // still upgrades to ORDER CONFIRMED without requiring a new redirect.
      // The user sees nothing change while cancelled — only if the webhook
      // fires and Supabase confirms "paid" does the screen flip to success.
      if (payment === "success" && isCatalystPay && order) {
        setPage("payment-return");
        setCatalystPayPending(true);
        const upgradeCatalystPayIfPaid = async (attempt) => {
          try {
            const { data } = await supabase.from("orders").select("status").eq("id", order).single();
            if (String(data?.status || "").toLowerCase() === "paid") {
              let payProvider = "CatalystPay BTC";
              try {
                const s = localStorage.getItem(`tbv-pay-method-${order}`);
                if (s) { payProvider = s; localStorage.removeItem(`tbv-pay-method-${order}`); }
              } catch {}
              const nextOrders = markOrderPaidById(order, payProvider, npId);
              if (currentUser?.email) setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
              const paidOrder = (Array.isArray(nextOrders) ? nextOrders : []).find((o) => o.id === order);
              const creditEmail = paidOrder?.email || currentUser?.email;
              const creditUsedCatalyst = Number(paidOrder?.storeCreditUsed || 0);
              if (creditUsedCatalyst > 0) {
                setStoreCredit((prev) => Math.max(0, prev - creditUsedCatalyst));
              }
              if (creditEmail) {
                loadStoreCredit(creditEmail);
                setTimeout(() => loadStoreCredit(creditEmail), 6000);
              }
              setPaymentReturn({ status: "success", order, paymentId: npId });
              setCatalystPayPending(false);
              setCart([]);
              return; // stop retrying
            }
          } catch {}
          // Retry 24× at 5s intervals = 120s total window for delayed webhooks.
          // After that the order is genuinely cancelled/expired — stop silently.
          if (attempt < 24) {
            setTimeout(() => upgradeCatalystPayIfPaid(attempt + 1), 5000);
          } else {
            setCatalystPayPending(false);
            setCatalystPayTimedOut(true);
          }
        };
        upgradeCatalystPayIfPaid(0);
        window.history.replaceState({}, "", `${window.location.origin}${window.location.pathname}`);
        return;
      }

      setPaymentReturn({ status: payment, order, paymentId: npId });
      setPage("payment-return");

      if (payment === "success" && order) {
        try {
          // Determine payment provider: Stripe uses ?provider=stripe in return URL
          let payProvider = urlProvider === "stripe" ? "Stripe" : "NOWPayments";
          try {
            const stored = localStorage.getItem(`tbv-pay-method-${order}`);
            if (stored) { payProvider = stored; localStorage.removeItem(`tbv-pay-method-${order}`); }
          } catch {}
          const nextOrders = markOrderPaidById(order, payProvider, npId);
          if (currentUser?.email) {
            setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
          }
          // Resync the displayed store-credit balance using the ORDER's own email,
          // not currentUser — currentUser's async session restore frequently hasn't
          // finished yet at this exact moment (right after the payment redirect),
          // so gating on currentUser?.email silently skipped this refresh and left
          // the header/account balance stale until the user happened to open the
          // account/checkout page later. The order itself always has the email
          // that was used to spend the credit, regardless of session state.
          const paidOrderForCredit = (Array.isArray(nextOrders) ? nextOrders : []).find((o) => o.id === order);
          const creditRefreshEmail = paidOrderForCredit?.email || currentUser?.email;
          // Optimistically deduct credits immediately so the balance updates
          // before the server-side webhook has a chance to run.
          const creditUsedNow = Number(paidOrderForCredit?.storeCreditUsed || 0);
          if (creditUsedNow > 0) {
            setStoreCredit((prev) => Math.max(0, prev - creditUsedNow));
          }
          if (creditRefreshEmail) {
            loadStoreCredit(creditRefreshEmail);
            // Re-sync after 6s to pick up any webhook-written value
            setTimeout(() => loadStoreCredit(creditRefreshEmail), 6000);
          }

          // Fallback for crypto orders: the DB "paid" status is normally set by the
          // NOWPayments IPN webhook, which can be delayed or occasionally never
          // arrive. Directly ask NOWPayments for the real status of this payment
          // and let the server apply the same paid-order logic once it's confirmed.
          // A single check right at redirect time is not enough — crypto payments
          // often aren't confirmed by the blockchain yet at that exact moment — so
          // retry a few times over several minutes instead of checking only once.
          // IMPORTANT: NOWPayments' hosted invoice page does NOT always append
          // NP_id/payment_id to the success redirect, so this used to silently
          // never run at all for some orders (order stuck as "checkout (clicked
          // pay)" forever, even though the customer paid and NOWPayments itself
          // shows "Finished"). We always have our own order id, so pass that too
          // and let the server look the payment up by order_id when npId is missing.
          if (payProvider === "NOWPayments" && (npId || order)) {
            const checkNowPaymentsStatus = async (attempt) => {
              try {
                const r = await fetch(`/api/verify-nowpayments-payment`, {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ payment_id: npId || undefined, order_id: order || undefined }),
                });
                const result = await r.json().catch(() => ({}));
                // Only stop retrying once the order is actually confirmed paid in the
                // database (dbMarkedPaid / alreadyPaidInDb) — NOT just when the payment
                // provider says "paid" (result.isPaid). The Supabase write can fail
                // transiently; if we stop on isPaid alone, a failed write leaves the
                // order permanently stuck even though a "payment confirmed" email
                // already went out.
                if (result?.dbMarkedPaid || result?.alreadyPaidInDb) return;
              } catch {}
              if (attempt < 20) {
                setTimeout(() => checkNowPaymentsStatus(attempt + 1), 20000);
              }
            };
            checkNowPaymentsStatus(0);
          }
        } catch (error) {
          console.error("Failed to mark order as paid", error);
        }
        setCart([]);
      }

      // Remove payment query params after processing so refresh does not reopen the payment result modal.
      window.history.replaceState({}, "", `${window.location.origin}${window.location.pathname}`);
    }
  }, [currentUser?.email]);

