  // Shop sidebar custom scrollbar sync + drag
  useEffect(() => {
    const el = shopSidebarScrollRef.current;
    const thumb = shopSidebarThumbRef.current;
    if (!el || !thumb) return;
    const getH = () => Math.max(24, (el.clientHeight / el.scrollHeight) * el.clientHeight);
    const sync = () => {
      if (el.scrollHeight <= el.clientHeight) { thumb.style.opacity = "0"; return; }
      thumb.style.opacity = "1";
      const h = getH(), max = el.clientHeight - h;
      thumb.style.height = h + "px";
      thumb.style.top = (el.scrollHeight > el.clientHeight ? (el.scrollTop / (el.scrollHeight - el.clientHeight)) * max : 0) + "px";
    };
    let sy = 0, ss = 0;
    const onDown = (e) => {
      e.preventDefault(); sy = e.clientY; ss = el.scrollTop; thumb.style.background = "#222";
      const onMove = (e) => { const h = getH(), max = el.clientHeight - h; el.scrollTop = ss + (max > 0 ? (e.clientY - sy) / max : 0) * (el.scrollHeight - el.clientHeight); };
      const onUp = () => { thumb.style.background = "#404040"; document.removeEventListener("mousemove", onMove); document.removeEventListener("mouseup", onUp); };
      document.addEventListener("mousemove", onMove); document.addEventListener("mouseup", onUp);
    };
    thumb.style.cursor = "grab"; thumb.style.pointerEvents = "auto";
    thumb.addEventListener("mousedown", onDown);
    el.addEventListener("scroll", sync, { passive: true });
    const ro = new ResizeObserver(sync); ro.observe(el);
    const t = setTimeout(sync, 0);
    return () => { el.removeEventListener("scroll", sync); thumb.removeEventListener("mousedown", onDown); ro.disconnect(); clearTimeout(t); };
  });

