  useEffect(() => {
    try {
      const savedAffiliates = JSON.parse(localStorage.getItem("tbv-affiliates") || "[]");
      const savedAffiliateAttribution = (localStorage.getItem("tbv-active-affiliate") || "").trim().toUpperCase();
      if (Array.isArray(savedAffiliates)) setAffiliateProfiles(normalizeAffiliateRows(savedAffiliates));
      if (savedAffiliateAttribution) setActiveAffiliateCode(savedAffiliateAttribution);
      const savedOrders = JSON.parse(localStorage.getItem("tbv-orders") || "[]");
      if (Array.isArray(savedOrders)) setAllOrders(savedOrders);
    } catch (error) {
      console.error("Failed to restore state", error);
    }

    // Handle password recovery link.
    // The IIFE at module top already set sessionStorage "tbv-pw-recovery" if the URL contained
    // type=recovery hash OR ?recovery=1 query param (which we set in redirectTo).
    // Here we clean the URL and ensure state is in sync.
    const urlHash = window.location.hash;
    const urlSearch = window.location.search;
    const hasRecoveryHash = urlHash.includes("type=recovery") || urlHash.includes("type%3Drecovery");
    const hasRecoveryParam = urlSearch.includes("recovery=1");

    if (hasRecoveryHash || hasRecoveryParam) {
      sessionStorage.setItem("tbv-pw-recovery", "1");
      // Clean the ?recovery=1 param from the URL bar so it doesn't confuse users
      if (hasRecoveryParam) {
        const clean = window.location.pathname + window.location.hash;
        window.history.replaceState(null, "", clean);
      }
      setAuthMode("reset");
      setPage("account");
    } else if (urlHash.includes("error=access_denied") || urlHash.includes("error_code=otp_expired")) {
      // Link expired — show forgot form with an error message
      sessionStorage.removeItem("tbv-pw-recovery");
      setAuthMode("forgot");
      setAccountMessage("Reset link has expired. Please request a new one.");
      setPage("account");
      window.history.replaceState(null, "", window.location.pathname);
    }

    // If sessionStorage flag is already set (e.g. user navigated back after first recovery click),
    // immediately enter reset mode before getSession runs.
    if (sessionStorage.getItem("tbv-pw-recovery")) {
      setAuthMode("reset");
      setPage("account");
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      // Don't restore a regular session while a recovery flow is active
      if (sessionStorage.getItem("tbv-pw-recovery")) { setAuthReady(true); return; }
      if (session?.user) {
        const user = userFromSupabase(session.user);
        setCurrentUser(user);
        setAccountForm({ email: user.email, password: "", confirmPassword: "" });
        fetchUserPromos(user.email, appliedPromo);
        loadStoreCredit(user.email);
      }
      setAuthReady(true);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === "PASSWORD_RECOVERY") {
        // Keep the recovery session alive. Also persist tokens to sessionStorage
        // so they survive React re-renders and can be used as a fallback.
        sessionStorage.setItem("tbv-pw-recovery", "1");
        if (session?.access_token) {
          sessionStorage.setItem("tbv-recovery-at", session.access_token);
          sessionStorage.setItem("tbv-recovery-rt", session.refresh_token || "");
        }
        setAuthMode("reset");
        setPage("account");
        return;
      }
      // Supabase sometimes fires SIGNED_IN right after PASSWORD_RECOVERY.
      // If we're in recovery mode, store tokens and stay in reset mode.
      if (event === "SIGNED_IN" && sessionStorage.getItem("tbv-pw-recovery")) {
        if (session?.access_token) {
          sessionStorage.setItem("tbv-recovery-at", session.access_token);
          sessionStorage.setItem("tbv-recovery-rt", session.refresh_token || "");
        }
        setAuthMode("reset");
        setPage("account");
        return;
      }
      if (session?.user) {
        const user = userFromSupabase(session.user);
        setCurrentUser(user);
        setAccountForm({ email: user.email, password: "", confirmPassword: "" });
        setContactForm((f) => ({ ...f, email: f.email || user.email || "" }));
      } else {
        setCurrentUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  

