  async function onPaypalApprove(data) {
    setPaypalPaymentLoading(true);
    setPaypalPaymentError("");
    // Use snapshot captured at createOrder time — guaranteed to match what PayPal charged
    const snap = paypalSnapshotRef.current;
    const snapTotal = snap?.total ?? Number(finalTotal.toFixed(2));
    const snapItems = snap?.items ?? cart.map((item) => ({ name: item.name, dose: item.dose, quantity: item.quantity, price: item.price, ...(item.fromWarehouse ? { fromWarehouse: item.fromWarehouse } : {}) }));
    const snapSubtotal = snap?.subtotal ?? Number(subtotal.toFixed(2));
    const snapShipping = snap?.shipping ?? Number(shipping.toFixed(2));
    const snapShippingType = snap?.shippingType ?? shippingType;
    const email = (checkoutForm.email || currentUser?.email || "").trim().toLowerCase();
    // Save a "pending" record BEFORE capture so we have a trace even if capture fails
    try {
      await supabase.from("orders").upsert({
        id: orderNumber,
        email,
        status: "pending",
        total: snapTotal,
        metadata: {
          id: orderNumber, email, status: "pending",
          paymentProvider: "PayPal", paypalOrderId: data.orderID,
          createdAt: new Date().toISOString(),
          total: snapTotal, subtotal: snapSubtotal, shipping: snapShipping,
          shippingType: snapShippingType,
          automaticDiscount: snap?.automaticDiscount ?? Number(automaticDiscount.toFixed(2)),
          promoDiscount: snap?.promoDiscount ?? Number(promoDiscount.toFixed(2)),
          promoCode: snap?.promoCode ?? appliedPromo?.code ?? "",
          affiliateDiscount: snap?.affiliateDiscount ?? Number(affiliateDiscount.toFixed(2)),
          affiliateCode: snap?.affiliateCode ?? affiliateTrackingCode,
          affiliateOwnerEmail: snap?.affiliateOwnerEmail ?? affiliateTrackingOwnerEmail,
          affiliateCommission: snap?.affiliateCommission ?? Number(affiliateCommission.toFixed(2)),
          storeCreditUsed: Number(storeCreditApplied.toFixed(2)),
          paypalFee: Number(paypalFee.toFixed(2)),
          firstName: checkoutForm.firstName || "", lastName: checkoutForm.lastName || "",
          country: checkoutForm.country || "", address: checkoutForm.address || "",
          address2: checkoutForm.address2 || "", city: checkoutForm.city || "",
          state: checkoutForm.state || "", postalCode: checkoutForm.postalCode || "",
          phone: checkoutForm.phone || "", items: snapItems,
        },
      });
    } catch (e) { console.error("Supabase pending upsert threw:", e); }
    try {
      const res = await fetch(`/api/paypal?action=capture-order&orderID=${data.orderID}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
      });
      const capture = await res.json();
      if (!res.ok) {
        const issue = capture?.details?.details?.[0]?.issue || capture?.details?.name || "";
        let friendly = capture?.error || "Failed to capture PayPal payment.";
        if (issue === "INSTRUMENT_DECLINED") {
          friendly = "Your bank declined the payment. If you received a confirmation request from your bank, please approve it and try again — or use a different card.";
        } else if (issue === "PAYER_ACTION_REQUIRED") {
          friendly = "Your bank requires extra verification. Please complete the confirmation step in your banking app and try again.";
        } else if (issue === "ORDER_ALREADY_CAPTURED") {
          friendly = "This order was already paid. Please contact support@10bottlevalue.co with your order number — we will confirm it shortly.";
        }
        throw new Error(friendly);
      }
      const captureId = capture?.purchase_units?.[0]?.payments?.captures?.[0]?.id ?? data.orderID;
      // Use actual captured amount from PayPal response as the source of truth
      const actualTotal = Number(capture?.purchase_units?.[0]?.payments?.captures?.[0]?.amount?.value ?? snapTotal);
      try {
        await supabase.from("orders").upsert({
          id: orderNumber,
          email,
          status: "paid",
          total: actualTotal,
          metadata: {
            id: orderNumber, email, status: "paid",
            paymentProvider: "PayPal", paypalOrderId: data.orderID,
            paypalCaptureId: captureId, paidAt: new Date().toISOString(),
            total: actualTotal, subtotal: snapSubtotal, shipping: snapShipping,
            shippingType: snapShippingType,
            automaticDiscount: snap?.automaticDiscount ?? Number(automaticDiscount.toFixed(2)),
            promoDiscount: snap?.promoDiscount ?? Number(promoDiscount.toFixed(2)),
            promoCode: snap?.promoCode ?? appliedPromo?.code ?? "",
            affiliateDiscount: snap?.affiliateDiscount ?? Number(affiliateDiscount.toFixed(2)),
            affiliateCode: snap?.affiliateCode ?? affiliateTrackingCode,
            affiliateOwnerEmail: snap?.affiliateOwnerEmail ?? affiliateTrackingOwnerEmail,
            affiliateCommission: snap?.affiliateCommission ?? Number(affiliateCommission.toFixed(2)),
            storeCreditUsed: Number(storeCreditApplied.toFixed(2)),
            paypalFee: Number(paypalFee.toFixed(2)),
            firstName: checkoutForm.firstName || "", lastName: checkoutForm.lastName || "",
            country: checkoutForm.country || "", address: checkoutForm.address || "",
            address2: checkoutForm.address2 || "",
            city: checkoutForm.city || "", postalCode: checkoutForm.postalCode || "",
            phone: checkoutForm.phone || "", items: snapItems,
          },
        });
      } catch (e) { console.error("Supabase paid upsert threw:", e); }
      const nextOrders = markOrderPaidById(orderNumber, "PayPal", captureId);
      if (currentUser?.email) setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
      setCart([]);
      setPaymentReturn({ status: "success", order: orderNumber, paymentId: captureId });
      setPage("payment-return");
    } catch (error) {
      setPaypalPaymentError(error?.message || "PayPal payment failed.");
    } finally {
      setPaypalPaymentLoading(false);
    }
  }

  async function checkNowPaymentStatus() {
    if (!nowPaymentData?.payment_id) return;

    try {
      const res = await fetch(
        `/api/payment-status?payment_id=${encodeURIComponent(
          nowPaymentData.payment_id
        )}`
      );
      const contentType = res.headers.get("content-type") || "";
      const rawText = await res.text();
      let data = null;

      if (contentType.includes("application/json")) {
        data = rawText ? JSON.parse(rawText) : {};
      } else {
        throw new Error(
          "Payment status API route is missing or returned HTML instead of JSON."
        );
      }

      if (!res.ok) {
        throw new Error(
          data?.message ||
            data?.error ||
            data?.status_text ||
            "Failed to check NOWPayments payment status."
        );
      }

      setNowPaymentStatus(data?.payment_status || "waiting");
      setNowPaymentData((current) => ({ ...current, ...data }));
      setNowPaymentError("");
    } catch (error) {
      setNowPaymentError(
        error?.message || "Failed to check NOWPayments payment status."
      );
    }
  }

  function applyPromoCode() {
    const normalizedCode = promoInput.trim().toUpperCase();

    if (!normalizedCode) {
      setPromoMessage(
        tx(
          "Enter a promo code.",
          "Введите промокод.",
          "Введіть промокод.",
          "Geben Sie einen Promocode ein.",
          "Introduce un código promocional."
        )
      );
      return;
    }

    const promo = promoCatalog[normalizedCode];

    if (appliedPromo && !(promo?.freeShipping)) {
      setPromoMessage(
        tx(
          "Remove the current promo code before applying another one.",
          "Удалите текущий промокод перед применением другого.",
          "Видаліть поточний промокод перед застосуванням іншого.",
          "Entfernen Sie den aktuellen Promocode, bevor Sie einen anderen anwenden.",
          "Elimina el código promocional actual antes de aplicar otro."
        )
      );
      return;
    }
    const matchedAffiliate = affiliateProfiles.find(
      (profile) => profile.code === normalizedCode && profile.active !== false
    );

    const matchedUserPromo = !promo && !matchedAffiliate
      ? userPromos.find((p) => p.code === normalizedCode && !p.used)
      : null;

    if (!promo && !matchedAffiliate && !matchedUserPromo) {
      setPromoMessage(
        tx(
          "Invalid promo code.",
          "Неверный промокод.",
          "Недійсний промокод.",
          "Ungültiger Promocode.",
          "Código promocional no válido."
        )
      );
      return;
    }

    if (promo?.emailLock && currentUser?.email?.toLowerCase() !== promo.emailLock.toLowerCase()) {
      setPromoMessage(
        tx(
          "Invalid promo code.",
          "Неверный промокод.",
          "Недійсний промокод.",
          "Ungültiger Promocode.",
          "Código promocional no válido."
        )
      );
      return;
    }

    if (matchedUserPromo) {
      if (usedPromoCodes.includes(normalizedCode)) {
        setPromoMessage(
          tx(
            "This promo code has already been used.",
            "Этот промокод уже использован.",
            "Цей промокод уже використано.",
            "Dieser Promocode wurde bereits verwendet.",
            "Este código promocional ya se ha utilizado."
          )
        );
        return;
      }
      setAffiliateDiscountDisabled(true);
      setAffiliateManuallyApplied(false);
      setActiveAffiliateCode("");
      try { localStorage.removeItem("tbv-active-affiliate"); } catch {}
      setAppliedPromo({ code: normalizedCode, rate: matchedUserPromo.rate, label: `${Math.round(matchedUserPromo.rate * 100)}% personal discount`, type: "user_promo", id: matchedUserPromo.id });
      setPromoInput("");
      setPromoMessage(
        tx(
          `${normalizedCode} applied successfully.`,
          `${normalizedCode} успешно применён.`,
          `${normalizedCode} успішно застосовано.`,
          `${normalizedCode} erfolgreich angewendet.`,
          `${normalizedCode} aplicado correctamente.`
        )
      );
      return;
    }

    if (matchedAffiliate) {
      if (
        currentUser?.email &&
        matchedAffiliate.ownerEmail === currentUser.email
      ) {
        setPromoMessage(
          tx(
            "You cannot use your own affiliate code.",
            "Вы не можете использовать собственный партнёрский код.",
            "Ви не можете використовувати власний партнерський код.",
            "Sie können Ihren eigenen Affiliate-Code nicht verwenden.",
            "No puedes usar tu propio código de afiliado."
          )
        );
        return;
      }

      if (usedPromoCodes.includes(normalizedCode)) {
        setPromoMessage(
          tx(
            "This promo code has already been used.",
            "Этот промокод уже использован.",
            "Цей промокод уже використано.",
            "Dieser Promocode wurde bereits verwendet.",
            "Este código promocional ya se ha utilizado."
          )
        );
        return;
      }

      setAppliedPromo(null);
      setAffiliateDiscountDisabled(false);
      setAffiliateManuallyApplied(true);
      setActiveAffiliateCode(matchedAffiliate.code);
      try {
        localStorage.setItem("tbv-active-affiliate", matchedAffiliate.code);
      } catch {}
      setPromoInput("");
      setPromoMessage(
        tx(
          isFirstTimeAffiliateBuyer
            ? `${matchedAffiliate.code} applied successfully. 5% off your first order applied.`
            : `${matchedAffiliate.code} applied successfully. Referral code active.`,
          isFirstTimeAffiliateBuyer
            ? `${matchedAffiliate.code} успешно применён. Скидка 5% на первый заказ активна.`
            : `${matchedAffiliate.code} успешно применён. Реферальный код активен.`,
          isFirstTimeAffiliateBuyer
            ? `${matchedAffiliate.code} успішно застосовано. Знижка 5% на перше замовлення активна.`
            : `${matchedAffiliate.code} успішно застосовано. Реферальний код активний.`,
          isFirstTimeAffiliateBuyer
            ? `${matchedAffiliate.code} erfolgreich angewendet. 5% Rabatt auf Ihre erste Bestellung.`
            : `${matchedAffiliate.code} erfolgreich angewendet. Empfehlungscode aktiv.`,
          isFirstTimeAffiliateBuyer
            ? `${matchedAffiliate.code} aplicado. 5% de descuento en tu primer pedido.`
            : `${matchedAffiliate.code} aplicado. Código de referido activo.`
        )
      );
      return;
    }

    if (usedPromoCodes.includes(normalizedCode)) {
      setPromoMessage(
        tx(
          "This promo code has already been used.",
          "Этот промокод уже использован.",
          "Цей промокод уже використано.",
          "Dieser Promocode wurde bereits verwendet.",
          "Este código promocional ya se ha utilizado."
        )
      );
      return;
    }

    if (promo.freeShipping) {
      setOwnerFreeShippingActive(true);
      setPromoInput("");
      setPromoMessage(
        tx(
          `${promo.code} applied — free shipping activated.`,
          `${promo.code} применён — бесплатная доставка активна.`,
          `${promo.code} застосовано — безкоштовна доставка активна.`,
          `${promo.code} angewendet — kostenloser Versand aktiviert.`,
          `${promo.code} aplicado — envío gratuito activado.`
        )
      );
      return;
    }
    setAffiliateDiscountDisabled(true);
    setAffiliateManuallyApplied(false);
    setActiveAffiliateCode("");
    try {
      localStorage.removeItem("tbv-active-affiliate");
    } catch {}
    setAppliedPromo(promo);
    if (currentUser?.email && promo.type === "general") {
      const userEmail = currentUser.email.trim().toLowerCase();
      supabase
        .from("user_promos")
        .select("id")
        .eq("email", userEmail)
        .eq("code", promo.code)
        .eq("used", false)
        .then(({ data }) => {
          if (!data || data.length === 0) {
            supabase.from("user_promos").insert({
              email: userEmail,
              code: promo.code,
              rate: promo.rate,
              used: false,
            }).then(({ error }) => {
              if (error) console.error("Failed to save promo to Supabase:", error.message);
            });
          }
        });
    }
    setPromoInput("");
    setPromoMessage(
      tx(
        `${promo.code} applied successfully.`,
        `${promo.code} успешно применён.`,
        `${promo.code} успішно застосовано.`,
        `${promo.code} erfolgreich angewendet.`,
        `${promo.code} aplicado correctamente.`
      )
    );
  }

