  function isAffiliateAccessUnlocked(email) {
    if (!email) return false;
    return Boolean(
      affiliateProfiles.find(
        (profile) =>
          normalizeEmail(profile.ownerEmail) === normalizeEmail(email) &&
          profile.active !== false
      ) || currentAffiliateProfile
    );
  }

  function requireAffiliateAccess() {
    if (!currentUser?.email) {
      showAffiliateMessage(t("affiliateSignInRequired"), true);
      return false;
    }

    if (isAffiliateAccessUnlocked(currentUser.email)) {
      return true;
    }

    showAffiliateMessage(
      tx(
        "Affiliate access is not active for this account. Contact support for manual approval.",
        "Партнёрский доступ не активен для этого аккаунта. Свяжитесь с поддержкой для ручного одобрения.",
        "Партнерський доступ не активний для цього акаунта. Звʼяжіться з підтримкою для ручного схвалення.",
        "Affiliate-Zugang ist für dieses Konto nicht aktiv. Kontaktieren Sie den Support für manuelle Freigabe.",
        "El acceso de afiliado no está activo para esta cuenta. Contacta con soporte para aprobación manual."
      ),
      true
    );
    return false;
  }

  function slugifyAffiliateCode(value) {
    return value
      .trim()
      .toUpperCase()
      .replace(/[^A-Z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 18);
  }

  async function issueAffiliateProfile() {
    const email = issueAffEmail.trim().toLowerCase();
    const code = issueAffCode.trim().toUpperCase();
    if (!email || !code) {
      setIssueAffMessage("Fill in email and code.");
      window.setTimeout(() => setIssueAffMessage(""), 4000);
      return;
    }
    try {
      const { error } = await supabase.from("affiliates").upsert({
        email: email,
        code: code,
      });
      if (error) {
        setIssueAffMessage(`Error: ${error.message}`);
      } else {
        setIssueAffMessage(`✓ Affiliate ${code} issued to ${email}`);
        setIssueAffEmail("");
        setIssueAffCode("");
        loadAffiliateProfilesFromSupabase();
      }
    } catch (e) {
      setIssueAffMessage("Error. Try again.");
    }
    window.setTimeout(() => setIssueAffMessage(""), 6000);
  }

  async function revokeAffiliateProfile() {
    const email = revokeAffEmail.trim().toLowerCase();
    if (!email) {
      setRevokeAffMessage("Enter an email.");
      window.setTimeout(() => setRevokeAffMessage(""), 4000);
      return;
    }
    try {
      const { data: existing } = await supabase.from("affiliates").select("code").eq("email", email).single();
      if (!existing) {
        setRevokeAffMessage(`No affiliate found for ${email}`);
        window.setTimeout(() => setRevokeAffMessage(""), 5000);
        return;
      }
      const { error } = await supabase.from("affiliates").update({ active: false }).eq("email", email);
      if (error) {
        setRevokeAffMessage(`Error: ${error.message}`);
      } else {
        setRevokeAffMessage(`✓ Affiliate access revoked for ${email} (code: ${existing.code})`);
        setRevokeAffEmail("");
        loadAffiliateProfilesFromSupabase();
      }
    } catch (e) {
      setRevokeAffMessage("Error. Try again.");
    }
    window.setTimeout(() => setRevokeAffMessage(""), 7000);
  }

