  function buildAffiliateLink(code) {
    const normalizedCode = String(code || "")
      .trim()
      .toUpperCase();
    if (!normalizedCode) return "";

    const baseUrl = SITE_URL.replace(/\/$/, "");
    return `${baseUrl}/?c=${normalizedCode.toLowerCase()}`;
  }

  function fallbackCopyText(text) {
    if (typeof document === "undefined" || !text) return false;

    try {
      const textArea = document.createElement("textarea");
      textArea.value = text;
      textArea.setAttribute("readonly", "");
      textArea.style.position = "fixed";
      textArea.style.opacity = "0";
      textArea.style.pointerEvents = "none";
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();
      textArea.setSelectionRange(0, text.length);
      const copied = document.execCommand("copy");
      document.body.removeChild(textArea);
      return copied;
    } catch {
      return false;
    }
  }

  function showAffiliateMessage(message, _isError) {
    setAffiliateMessage(String(message || ""));
    setAffiliateMessagePulse((current) => current + 1);
    setAffiliateMessageVisible(true);

    if (typeof window !== "undefined") {
      window.clearTimeout(window.__tbvAffiliateMessageFadeTimeout);
      window.clearTimeout(window.__tbvAffiliateMessageTimeout);

      window.__tbvAffiliateMessageFadeTimeout = window.setTimeout(() => {
        setAffiliateMessageVisible(false);
      }, 5800);

      window.__tbvAffiliateMessageTimeout = window.setTimeout(() => {
        setAffiliateMessage("");
      }, 6500);
    }
  }

  function showAffiliateCopyMessage(message) {
    setAffiliateMessage("");
    setCopiedAffiliateLink(true);
    setAffiliateMessagePulse((current) => current + 1);
    setAffiliateMessageVisible(true);

    window.clearTimeout(window.__tbvAffiliateCopyTimeout);
    window.clearTimeout(window.__tbvAffiliateCopyFadeTimeout);

    window.__tbvAffiliateCopyFadeTimeout = window.setTimeout(() => {
      setAffiliateMessageVisible(false);
    }, 4200);

    window.__tbvAffiliateCopyTimeout = window.setTimeout(() => {
      setAffiliateMessage("");
      setCopiedAffiliateLink(false);
    }, 5000);
  }

  async function copyAffiliateLink(code) {
    if (!requireAffiliateAccess()) {
      return;
    }

    const link = buildAffiliateLink(code);
    if (!link) {
      showAffiliateCopyMessage(
        tx(
          "Affiliate link is unavailable right now.",
          "Партнёрская ссылка сейчас недоступна.",
          "Партнерське посилання зараз недоступне.",
          "Der Affiliate-Link ist derzeit nicht verfügbar.",
          "El enlace de afiliado no está disponible ahora."
        )
      );
      return;
    }

    try {
      if (navigator?.clipboard?.writeText && window.isSecureContext) {
        await navigator.clipboard.writeText(link);
        showAffiliateCopyMessage(
          tx(
            "AFFILIATE LINK COPIED",
            "ПАРТНЁРСКАЯ ССЫЛКА СКОПИРОВАНА",
            "ПАРТНЕРСЬКЕ ПОСИЛАННЯ СКОПІЙОВАНО",
            "AFFILIATE-LINK KOPIERT",
            "ENLACE DE AFILIADO COPIADO"
          )
        );
        return;
      }
    } catch (error) {
      console.error("Failed to copy affiliate link", error);
    }

    if (fallbackCopyText(link)) {
      showAffiliateCopyMessage(
        tx(
          "AFFILIATE LINK COPIED",
          "ПАРТНЁРСКАЯ ССЫЛКА СКОПИРОВАНА",
          "ПАРТНЕРСЬКЕ ПОСИЛАННЯ СКОПІЙОВАНО",
          "AFFILIATE-LINK KOPIERT",
          "ENLACE DE AFILIADO COPIADO"
        )
      );
      return;
    }

    showAffiliateCopyMessage(
      tx(
        `Copy this link manually: ${link}`,
        `Скопируйте ссылку вручную: ${link}`,
        `Скопіюйте посилання вручну: ${link}`,
        `Kopieren Sie diesen Link manuell: ${link}`,
        `Copia este enlace manualmente: ${link}`
      )
    );
  }

  function validateCheckoutForm(syncedForm) {
    const errors = {};
    const email = (syncedForm.email || "").trim();
    const phone = (syncedForm.phone || "").trim();

    if (!email) errors.email = true;
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.email = true;

    if (!syncedForm.firstName?.trim()) errors.firstName = true;
    if (!syncedForm.lastName?.trim()) errors.lastName = true;
    if (!syncedForm.country?.trim()) errors.country = true;
    if (!syncedForm.address?.trim()) errors.address = true;
    if (!syncedForm.city?.trim()) errors.city = true;
    if (!syncedForm.postalCode?.trim()) errors.postalCode = true;
    if (syncedForm.country?.trim() === "Mexico") {
      const taxId = (syncedForm.taxId || "").trim().replace(/\s/g, "");
      if (!taxId || taxId.length < 12 || taxId.length > 13) errors.taxId = true;
    }

    if (!phone) {
      errors.phone = true;
    } else {
      const digits = phone.replace(/\D/g, "");
      const uniqueDigits = new Set(digits).size;
      if (digits.length < 7 || digits.length > 15 || uniqueDigits < 3) {
        errors.phone = true;
      }
    }

    return errors;
  }

  async function handleCheckout() {
    if (!currentUser?.email) {
      setPendingCheckoutAfterAuth(true);
      setAuthMode("create");
      setAccountMessage(
        tx(
          "To place an order, please register.",
          "Чтобы сделать заказ, пожалуйста, зарегистрируйтесь.",
          "Щоб зробити замовлення, будь ласка, зареєструйтесь.",
          "Um eine Bestellung aufzugeben, registrieren Sie sich bitte.",
          "Para realizar un pedido, regístrese por favor."
        )
      );
      setCheckoutMessage(
        tx(
          "Registration required to place an order.",
          "Для оформления заказа требуется регистрация.",
          "Для оформлення замовлення потрібна реєстрація.",
          "Für eine Bestellung ist eine Registrierung erforderlich.",
          "Se requiere registro para realizar un pedido."
        )
      );
      setPage("account");
      if (typeof window !== "undefined") {
        window.scrollTo({ top: 0, behavior: "smooth" });
      }
      return;
    }

    const syncedForm = {
      email: checkoutInputRefs.current.email?.value || checkoutForm.email,
      firstName:
        checkoutInputRefs.current.firstName?.value || checkoutForm.firstName,
      lastName:
        checkoutInputRefs.current.lastName?.value || checkoutForm.lastName,
      country: checkoutInputRefs.current.country?.value || checkoutForm.country,
      address: checkoutInputRefs.current.address?.value || checkoutForm.address,
      address2: checkoutInputRefs.current.address2?.value || checkoutForm.address2,
      city: checkoutInputRefs.current.city?.value || checkoutForm.city,
      state: checkoutInputRefs.current.state?.value || checkoutForm.state,
      postalCode:
        checkoutInputRefs.current.postalCode?.value || checkoutForm.postalCode,
      phone: checkoutInputRefs.current.phone?.value || checkoutForm.phone,
      taxId: checkoutForm.taxId,
    };

    setCheckoutForm(syncedForm);
    setCountrySearch(syncedForm.country || "");

    if (cart.length === 0) {
      setCheckoutMessage(t("cartEmpty"));
      return;
    }

    const errors = validateCheckoutForm(syncedForm);

    setCheckoutErrors(errors);

    if (Object.keys(errors).length > 0) {
      setCheckoutMessage(
        tx(
          "Please correctly fill in all required fields.",
          "Заполните все обязательные поля корректно.",
          "Заповніть усі обовʼязкові поля коректно.",
          "Bitte füllen Sie alle Pflichtfelder korrekt aus.",
          "Completa correctamente todos los campos obligatorios."
        )
      );
      const firstErrorField = Object.keys(errors)[0];
      const fieldRef = checkoutInputRefs.current[firstErrorField];
      if (fieldRef) {
        setTimeout(() => {
          fieldRef.scrollIntoView({ behavior: "smooth", block: "center" });
          fieldRef.focus();
        }, 50);
      } else if (formSectionRef.current) {
        setTimeout(() => {
          formSectionRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
        }, 50);
      }
      return;
    }

    if (!researchAccepted || !qualifiedAccepted || !termsAccepted) {
      setCheckoutMessage(
        !researchAccepted
          ? tx(
              "Please confirm that you are over 21 and understand that all products are for research use only before continuing.",
              "Перед продолжением подтвердите, что вам больше 21 года и вы понимаете, что все продукты только для исследовательского использования.",
              "Перед продовженням підтвердіть, що вам більше 21 року і ви розумієте, що всі продукти лише для дослідницького використання.",
              "Bitte bestätigen Sie vor dem Fortfahren, dass Sie über 21 Jahre alt sind und verstehen, dass alle Produkte nur für Forschungszwecke bestimmt sind.",
              "Antes de continuar, confirma que tienes más de 21 años y entiendes que todos los productos son solo para uso de investigación."
            )
          : !qualifiedAccepted
          ? tx(
              "Please confirm that you are purchasing for laboratory, analytical, or scientific research purposes only and are qualified to handle such materials.",
              "Подтвердите, что покупаете только для лабораторных, аналитических или научных исследовательских целей и квалифицированы для работы с такими материалами.",
              "Підтвердіть, що купуєте лише для лабораторних, аналітичних або наукових дослідницьких цілей і кваліфіковані для роботи з такими матеріалами.",
              "Bitte bestätigen Sie, dass Sie ausschließlich für Labor-, Analyse- oder wissenschaftliche Forschungszwecke kaufen und für den Umgang mit solchen Materialien qualifiziert sind.",
              "Confirma que compras únicamente para fines de investigación de laboratorio, analíticos o científicos y que estás cualificado para manejar dichos materiales."
            )
          : tx(
              "Please read and agree to the Terms, Privacy, Refund, and Shipping policies before continuing.",
              "Перед продолжением прочитайте и согласитесь с условиями, политикой конфиденциальности, возврата и доставки.",
              "Перед продовженням прочитайте та погодьтеся з умовами, політикою конфіденційності, повернення та доставки.",
              "Bitte lesen und akzeptieren Sie vor dem Fortfahren die Bedingungen, Datenschutz-, Rückerstattungs- und Versandrichtlinien.",
              "Antes de continuar, lee y acepta los términos, la política de privacidad, reembolso y envío."
            )
      );
      if (termsSectionRef.current) {
        setTimeout(() => {
          termsSectionRef.current.scrollIntoView({ behavior: "smooth", block: "center" });
        }, 50);
      }
      setCheckboxHighlight(true);
      setTimeout(() => setCheckboxHighlight(false), 900);
      return;
    }

    const generatedOrderNumber = `INV-${Math.random()
      .toString(36)
      .slice(2, 10)
      .toUpperCase()}`;
    const normalizedEmail = currentUser.email.trim().toLowerCase();
    setOrderNumber(generatedOrderNumber);
    setCheckoutMessage("");

    if (currentUser?.email) {
      const updatedUser = {
        ...currentUser,
        email: normalizedEmail,
        firstName: syncedForm.firstName,
        lastName: syncedForm.lastName,
        country: syncedForm.country,
        address: syncedForm.address,
        city: syncedForm.city,
        postalCode: syncedForm.postalCode,
        phone: syncedForm.phone,
      };

      setCurrentUser(updatedUser);
      setRegisteredUsers((current) =>
        current.map((user) =>
          user.email === currentUser.email ? { ...user, ...updatedUser } : user
        )
      );
    }

    const orderRecord = {
      id: generatedOrderNumber,
      email: normalizedEmail,
      status: "pending",
      paymentProvider: "pending",
      paymentId: "",
      paidAt: "",
      confirmationEmailSentAt: "",
      createdAt: new Date().toISOString(),
      shippingType: effectiveShippingType,
      firstName: syncedForm.firstName || "",
      lastName: syncedForm.lastName || "",
      country: syncedForm.country || "",
      address: syncedForm.address || "",
      address2: syncedForm.address2 || "",
      city: syncedForm.city || "",
      state: syncedForm.state || "",
      postalCode: syncedForm.postalCode || "",
      phone: syncedForm.phone || "",
      taxId: syncedForm.taxId || "",
      orderNotes: [(checkoutForm.orderNotes || "").trim(), checkoutForm.carrierPreference ? `Carrier preference: ${checkoutForm.carrierPreference}` : ""].filter(Boolean).join("\n"),
      subtotal: Number(subtotal.toFixed(2)),
      shipping: Number(shipping.toFixed(2)),
      automaticDiscount: Number(automaticDiscount.toFixed(2)),
      promoDiscount: Number(promoDiscount.toFixed(2)),
      promoCode: appliedPromo?.code || "",
      affiliateDiscount: Number(affiliateDiscount.toFixed(2)),
         cryptoDiscount: Number(cryptoDiscountAmount.toFixed(2)),
      storeCreditUsed: Number(storeCreditApplied.toFixed(2)),
      total: Number(finalTotal.toFixed(2)),
      affiliateCode: affiliateTrackingCode,
      affiliateOwnerEmail: affiliateTrackingOwnerEmail,
      affiliateCommission: Number(affiliateCommission.toFixed(2)),
      items: cart.map((item) => ({
        name: item.name,
        dose: item.dose,
        quantity: item.quantity,
        price: item.price,
        ...(item.fromWarehouse ? { fromWarehouse: item.fromWarehouse } : {}),
        ...(item.noteLabel ? { noteLabel: item.noteLabel } : {}),
      })),
    };

    try {
      const existingOrders = JSON.parse(
        localStorage.getItem("tbv-orders") || "[]"
      );
      const nextOrders = Array.isArray(existingOrders)
        ? [orderRecord, ...existingOrders]
        : [orderRecord];
      localStorage.setItem("tbv-orders", JSON.stringify(nextOrders));
      setAllOrders(nextOrders);
      setUserOrders(getPaidOrdersForEmail(normalizedEmail, nextOrders));
    } catch (error) {
      console.error("Failed to save order", error);
    }

    window.scrollTo({ top: 0, behavior: "instant" });
    setPaymentTimer(59 * 60 + 45);
    setNowPaymentData(null);
    setNowPaymentStatus("waiting");
    setNowPaymentError("");
    setPaypalPaymentError("");
    setCheckoutStep("payment");
    // On mobile, scroll down so the Stripe loading form is visible
    if (window.innerWidth < 768) {
      setTimeout(() => window.scrollTo({ top: 640, behavior: "smooth" }), 80);
    }

    supabase
      .from("orders")
      .upsert({
        id: orderRecord.id,
        email: orderRecord.email,
        status: orderRecord.status ?? "pending",
        total: orderRecord.total ?? 0,
        metadata: orderRecord,
      })
      .then(({ error: sbErr }) => {
        if (sbErr) console.error("Supabase: insert order failed:", sbErr.message);
      })
      .catch((e) => {
        console.error("Supabase: insert order threw:", e);
      });
  }

  async function handlePayWithCredits() {
    if (!currentUser?.email) return;
    if (!researchAccepted || !qualifiedAccepted || !termsAccepted) {
      setCheckboxHighlight(true);
      setTimeout(() => setCheckboxHighlight(false), 900);
      if (termsSectionRef.current) termsSectionRef.current.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }
    const syncedForm = {
      email: checkoutInputRefs.current.email?.value || checkoutForm.email || currentUser.email,
      firstName: checkoutInputRefs.current.firstName?.value || checkoutForm.firstName,
      lastName: checkoutInputRefs.current.lastName?.value || checkoutForm.lastName,
      country: checkoutInputRefs.current.country?.value || checkoutForm.country,
      address: checkoutInputRefs.current.address?.value || checkoutForm.address,
      address2: checkoutInputRefs.current.address2?.value || checkoutForm.address2,
      city: checkoutInputRefs.current.city?.value || checkoutForm.city,
      state: checkoutInputRefs.current.state?.value || checkoutForm.state,
      postalCode: checkoutInputRefs.current.postalCode?.value || checkoutForm.postalCode,
      phone: checkoutInputRefs.current.phone?.value || checkoutForm.phone,
      taxId: checkoutForm.taxId,
    };
    const errors = validateCheckoutForm(syncedForm);
    setCheckoutErrors(errors);
    if (Object.keys(errors).length > 0) {
      const firstField = Object.keys(errors)[0];
      const ref = checkoutInputRefs.current[firstField];
      if (ref) { ref.scrollIntoView({ behavior: "smooth", block: "center" }); ref.focus(); }
      else if (formSectionRef.current) formSectionRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
      return;
    }
    const generatedOrderNumber = `INV-${Math.random().toString(36).slice(2, 10).toUpperCase()}`;
    const normalizedEmail = currentUser.email.trim().toLowerCase();
    const paidAt = new Date().toISOString();
    const orderRecord = {
      id: generatedOrderNumber,
      email: normalizedEmail,
      status: "paid",
      paymentProvider: "StoreCredit",
      paymentId: "",
      paidAt,
      confirmationEmailSentAt: "",
      createdAt: paidAt,
      shippingType: effectiveShippingType,
      firstName: syncedForm.firstName || "",
      lastName: syncedForm.lastName || "",
      country: syncedForm.country || "",
      address: syncedForm.address || "",
      address2: syncedForm.address2 || "",
      city: syncedForm.city || "",
      state: syncedForm.state || "",
      postalCode: syncedForm.postalCode || "",
      phone: syncedForm.phone || "",
      taxId: syncedForm.taxId || "",
      orderNotes: [(checkoutForm.orderNotes || "").trim(), checkoutForm.carrierPreference ? `Carrier preference: ${checkoutForm.carrierPreference}` : ""].filter(Boolean).join("\n"),
      subtotal: Number(subtotal.toFixed(2)),
      shipping: Number(shipping.toFixed(2)),
      automaticDiscount: Number(automaticDiscount.toFixed(2)),
      promoDiscount: Number(promoDiscount.toFixed(2)),
      promoCode: appliedPromo?.code || "",
      affiliateDiscount: Number(affiliateDiscount.toFixed(2)),
         cryptoDiscount: Number(cryptoDiscountAmount.toFixed(2)),
      storeCreditUsed: Number(storeCreditApplied.toFixed(2)),
      total: 0,
      affiliateCode: affiliateTrackingCode,
      affiliateOwnerEmail: affiliateTrackingOwnerEmail,
      affiliateCommission: Number(affiliateCommission.toFixed(2)),
      items: cart.map((item) => ({
        name: item.name, dose: item.dose, quantity: item.quantity, price: item.price,
        ...(item.fromWarehouse ? { fromWarehouse: item.fromWarehouse } : {}),
        ...(item.noteLabel ? { noteLabel: item.noteLabel } : {}),
      })),
    };
    try {
      const existing = JSON.parse(localStorage.getItem("tbv-orders") || "[]");
      const next = Array.isArray(existing) ? [orderRecord, ...existing] : [orderRecord];
      localStorage.setItem("tbv-orders", JSON.stringify(next));
      setAllOrders(next);
      setUserOrders(getPaidOrdersForEmail(normalizedEmail, next));
    } catch (e) { console.error("Credit order localStorage failed", e); }
    try {
      await supabase.from("orders").upsert({
        id: orderRecord.id, email: orderRecord.email, status: "paid",
        paid_at: paidAt, total: 0, metadata: orderRecord,
      });
    } catch (e) { console.error("Credit order Supabase failed", e); }
    try {
      const { data: creditRow } = await supabase.from("user_credits").select("amount").eq("email", normalizedEmail).order("updated_at", { ascending: false }).limit(1).single();
      const currentAmt = creditRow ? Number(creditRow.amount) : 0;
      const newAmt = Math.max(0, currentAmt - Number(storeCreditApplied.toFixed(2)));
      // Use UPDATE to avoid duplicate-row issues; INSERT only if no row exists
      const { error: updateErr } = await supabase.from("user_credits").update({ amount: newAmt, updated_at: new Date().toISOString() }).eq("email", normalizedEmail);
      if (updateErr || !creditRow) {
        await supabase.from("user_credits").insert({ email: normalizedEmail, amount: newAmt, updated_at: new Date().toISOString() });
      }
      // Delete any duplicate rows (keep the one with correct balance, delete extras)
      const { data: allRows } = await supabase.from("user_credits").select("id, amount, updated_at").eq("email", normalizedEmail).order("updated_at", { ascending: false });
      if (allRows && allRows.length > 1) {
        const idsToDelete = allRows.slice(1).map(r => r.id);
        await supabase.from("user_credits").delete().in("id", idsToDelete);
      }
      setStoreCredit(newAmt);
    } catch (e) { console.error("Credit deduction failed", e); }
    setCreditPayAmount(Number(storeCreditApplied.toFixed(2)));
    setCreditPayAnimating(true);
    setTimeout(() => {
      setCreditPayAnimating(false);
      setCart([]);
      setPaymentReturn({ status: "success", order: generatedOrderNumber });
      setPage("payment-return");
      refreshUserOrdersFromSupabase(normalizedEmail);
    }, 2800);
  }

  function updateCheckoutField(field, value) {
    setCheckoutForm((current) => ({
      ...current,
      [field]: value,
    }));

    setCheckoutErrors((current) => {
      if (!current[field]) return current;
      const next = { ...current };
      delete next[field];
      return next;
    });

    if (checkoutMessage) {
      setCheckoutMessage("");
    }
    if (checkoutStep === "payment") {
      setCheckoutStep("details");
      setPaymentTimer(59 * 60 + 45);
    }
  }

  function openCountryDropdown() {
    if (countryDropdownRef.current) {
      const rect = countryDropdownRef.current.getBoundingClientRect();
      setCountryDropdownRect({ top: rect.bottom + 8, left: rect.left, width: rect.width });
    }
    setIsCountryDropdownOpen(true);
    // Always scroll list to top when opening
    setTimeout(() => {
      if (countryDropdownScrollRef.current) countryDropdownScrollRef.current.scrollTop = 0;
    }, 0);
  }

  function handleCountryInputChange(value) {
    const hasUsWarehouseItems = cart.some(i => i.fromWarehouse === "us");
    setCountrySearch(value);
    const exactMatch = countryOptions.find(
      (c) => c.toLowerCase() === value.toLowerCase().trim()
    );
    if (exactMatch) {
      if (hasUsWarehouseItems && exactMatch !== "United States") {
        updateCheckoutField("country", exactMatch);
      } else {
        updateCheckoutField("country", exactMatch);
        setCheckoutErrors((prev) => { const n = { ...prev }; delete n.country; return n; });
      }
    } else {
      updateCheckoutField("country", "");
    }
    openCountryDropdown();
  }

  function selectCountry(country) {
    const hasUsWarehouseItems = cart.some(i => i.fromWarehouse === "us");
    if (hasUsWarehouseItems && country !== "United States") {
      setCountrySearch("United States");
      updateCheckoutField("country", "United States");
      setIsCountryDropdownOpen(false);
      setCountryDropdownRect(null);
      return;
    }
    // country selected — no auto-switch; Express availability is enforced in the dropdown
    setCountrySearch(country);
    updateCheckoutField("country", country);
    setIsCountryDropdownOpen(false);
    setCountryDropdownRect(null);
  }

  function makeProductSlug(p) {
    return `${p.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${p.dose.toLowerCase().replace(/\s+/g, "")}`;
  }

  function openProduct(product) {
    savedShopScrollY.current = window.scrollY;
    savedSidebarScrollTop.current = shopSidebarScrollRef.current?.scrollTop ?? 0;
    productOriginPage.current = page;
    setSelectedProduct(product);
    setCoaPage(0);
    setCoaLightbox(false);
    setPage("product");
    window.scrollTo({ top: 0, behavior: "auto" });
    const affCode = currentAffiliateProfile?.code;
    const newPath = "/" + makeProductSlug(product) + (affCode ? "?c=" + affCode.toLowerCase() : "");
    window.history.replaceState({}, "", newPath);
  }

  async function handleForgotSubmit(e) {
    e.preventDefault();
    const email = forgotEmail.trim().toLowerCase();
    if (!email) { setAccountMessage(tx("Enter your email.", "Введите email.", "Введіть email.", "E-Mail eingeben.", "Introduce tu email.")); return; }
    setAccountMessage(tx("Sending reset link…", "Отправляем ссылку…", "Надсилаємо посилання…", "Link wird gesendet…", "Enviando enlace…"));
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin + "/?recovery=1",
      });
      if (error) { setAccountMessage(error.message); return; }
      setAccountMessage(tx("Reset link sent! Check your email.", "Ссылка отправлена! Проверьте email.", "Посилання надіслано! Перевірте email.", "Link gesendet! E-Mail prüfen.", "¡Enlace enviado! Revisa tu email."));
      setAuthMode("signin");
    } catch { setAccountMessage(tx("Failed to send reset link.", "Не удалось отправить ссылку.", "Не вдалося надіслати посилання.", "Link konnte nicht gesendet werden.", "No se pudo enviar el enlace.")); }
  }

  async function handleResetSubmit(e) {
    e.preventDefault();
    const { password, confirmPassword } = resetForm;
    if (!password) { setAccountMessage(tx("Fill all fields.", "Заполните все поля.", "Заповніть усі поля.", "Alle Felder ausfüllen.", "Completa todos los campos.")); return; }
    if (password.length < 6) { setAccountMessage(tx("Password too short.", "Пароль слишком короткий.", "Пароль занадто короткий.", "Passwort zu kurz.", "Contraseña muy corta.")); return; }
    if (password !== confirmPassword) { setAccountMessage(tx("Passwords do not match.", "Пароли не совпадают.", "Паролі не збігаються.", "Passwörter stimmen nicht überein.", "Las contraseñas no coinciden.")); return; }
    try {
      // Attempt 1: session should still be active from the recovery link
      let { error } = await supabase.auth.updateUser({ password });

      // Attempt 2: if session lost, restore it from sessionStorage tokens and retry
      if (error) {
        const at = sessionStorage.getItem("tbv-recovery-at");
        const rt = sessionStorage.getItem("tbv-recovery-rt");
        if (at) {
          const { error: sessErr } = await supabase.auth.setSession({ access_token: at, refresh_token: rt || at });
          if (!sessErr) {
            const { error: retryErr } = await supabase.auth.updateUser({ password });
            error = retryErr;
          }
        }
      }

      if (error) {
        // Truly expired — send back to forgot form
        sessionStorage.removeItem("tbv-pw-recovery");
        sessionStorage.removeItem("tbv-recovery-at");
        sessionStorage.removeItem("tbv-recovery-rt");
        setRecoverySession(null);
        setAuthMode("forgot");
        setAccountMessage(tx("Reset link expired. Please request a new one.", "Ссылка сброса устарела. Запросите новую.", "Посилання застаріло. Запросіть нове.", "Reset-Link abgelaufen. Bitte neuen anfordern.", "Enlace expirado. Solicita uno nuevo."));
        return;
      }

      // Success — sign out cleanly and go to login
      await supabase.auth.signOut();
      setCurrentUser(null);
      sessionStorage.removeItem("tbv-pw-recovery");
      sessionStorage.removeItem("tbv-recovery-at");
      sessionStorage.removeItem("tbv-recovery-rt");
      setRecoverySession(null);
      setAuthMode("signin");
      setResetForm({ code: "", password: "", confirmPassword: "" });
      setForgotEmail("");
      setAccountMessage(tx("Password updated! Sign in with your new password.", "Пароль обновлён! Войдите с новым паролем.", "Пароль оновлено! Увійдіть з новим паролем.", "Passwort aktualisiert! Mit neuem Passwort einloggen.", "¡Contraseña actualizada! Inicia sesión con tu nueva contraseña."));
    } catch { setAccountMessage(tx("Verification failed.", "Ошибка проверки.", "Помилка перевірки.", "Fehler bei der Verifizierung.", "Error de verificación.")); }
  }

  async function sendRegistrationEmail(email) {
    try {
      await fetch("/api/send-registration-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });
    } catch (error) {
      console.error("Failed to send registration email", error);
    }
  }

  async function handleAccountSubmit(e) {
    e.preventDefault();

    const email = accountForm.email.trim().toLowerCase();
    const password = accountForm.password;
    const confirmPassword = accountForm.confirmPassword;
    const registrationPromoCode = String(
      accountPromoCodeInput || getResolvedAffiliateCode() || ""
    )
      .trim()
      .toUpperCase();

    if (!email || !password) {
      setAccountMessage(
        tx(
          "Please fill in all required fields.",
          "Заполните все обязательные поля.",
          "Заповніть усі обовʼязкові поля.",
          "Bitte füllen Sie alle Pflichtfelder aus.",
          "Completa todos los campos obligatorios."
        )
      );
      return;
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setAccountMessage(
        tx(
          "Enter a valid email address.",
          "Введите корректный email.",
          "Введіть коректний email.",
          "Geben Sie eine gültige E-Mail-Adresse ein.",
          "Introduce un email válido."
        )
      );
      return;
    }

    if (password.length < 6) {
      setAccountMessage(
        tx(
          "Password must be at least 6 characters.",
          "Пароль должен быть не короче 6 символов.",
          "Пароль має містити щонайменше 6 символів.",
          "Das Passwort muss mindestens 6 Zeichen lang sein.",
          "La contraseña debe tener al menos 6 caracteres."
        )
      );
      return;
    }

    if (authMode === "create") {
      if (password !== confirmPassword) {
        setAccountMessage(
          tx(
            "Passwords do not match.",
            "Пароли не совпадают.",
            "Паролі не збігаються.",
            "Passwörter stimmen nicht überein.",
            "Las contraseñas no coinciden."
          )
        );
        return;
      }

      const matchedRegistrationAffiliate = affiliateProfiles.find(
        (profile) => profile.code === registrationPromoCode && profile.active !== false
      );

      if (registrationPromoCode && !matchedRegistrationAffiliate) {
        setAccountMessage(
          tx(
            "Invalid affiliate code.",
            "Неверный партнёрский код.",
            "Недійсний партнерський код.",
            "Ungültiger Affiliate-Code.",
            "Código de afiliado no válido."
          )
        );
        return;
      }

      setAccountMessage(tx("Creating account…", "Создаём аккаунт…", "Створюємо акаунт…", "Konto wird erstellt…", "Creando cuenta…"));
      const { data: signUpData, error: signUpError } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            affiliateCode: (activeAffiliateCode || browserAffiliateCode || registrationPromoCode || "").trim().toUpperCase(),
            promoLockedAt: (activeAffiliateCode || browserAffiliateCode || registrationPromoCode) ? new Date().toISOString() : "",
          },
        },
      });

      if (signUpError) {
        setAccountMessage(signUpError.message);
        return;
      }

      try { syncUserPaidOrders(email); } catch {}
      sendRegistrationEmail(email);

      if (signUpData.user) {
        const newUser = userFromSupabase(signUpData.user);
        setCurrentUser(newUser);
        setAccountForm({ email: newUser.email, password: "", confirmPassword: "" });
        setAccountPromoCodeInput("");
        fetchUserPromos(newUser.email, appliedPromo);
        loadStoreCredit(newUser.email);
        if (registrationPromoCode) {
          setActiveAffiliateCode(registrationPromoCode);
          try { localStorage.setItem("tbv-active-affiliate", registrationPromoCode); } catch {}
        } else {
          setActiveAffiliateCode("");
          try { localStorage.removeItem("tbv-active-affiliate"); } catch {}
        }
        setAccountMessage("");
        if (pendingCheckoutAfterAuth && cart.length > 0) {
          setPendingCheckoutAfterAuth(false);
          setPage("cart");
        }
      } else {
        setAccountMessage(tx(
          "Account created! Check your email to confirm.",
          "Аккаунт создан! Проверьте email для подтверждения.",
          "Акаунт створено! Перевірте email для підтвердження.",
          "Konto erstellt! Bestätigungs-E-Mail prüfen.",
          "¡Cuenta creada! Revisa tu email para confirmar."
        ));
      }
      return;
    }

    // Clear any lingering recovery session before a normal sign-in so the
    // SIGNED_IN auth event is not mistakenly treated as part of a reset flow.
    sessionStorage.removeItem("tbv-pw-recovery");
    sessionStorage.removeItem("tbv-recovery-at");
    sessionStorage.removeItem("tbv-recovery-rt");
    setAccountMessage(tx("Signing in…", "Входим…", "Входимо…", "Anmelden…", "Iniciando sesión…"));
    const { data: signInData, error: signInError } = await supabase.auth.signInWithPassword({ email, password });

    if (signInError) {
      setAccountMessage(tx(
        "Invalid email or password.",
        "Неверный email или пароль.",
        "Недійсний email або пароль.",
        "Ungültige E-Mail oder ungültiges Passwort.",
        "Email o contraseña no válidos."
      ));
      return;
    }

    const loggedInUser = userFromSupabase(signInData.user);
    setCurrentUser(loggedInUser);
    syncUserPaidOrders(loggedInUser.email);
    fetchUserPromos(loggedInUser.email, appliedPromo);
    loadStoreCredit(loggedInUser.email);
    setAccountForm({ email: loggedInUser.email, password: "", confirmPassword: "" });
    setAccountPromoCodeInput("");
    if (loggedInUser.affiliateCode) setActiveAffiliateCode(loggedInUser.affiliateCode);
    setAccountMessage("");
    if (pendingCheckoutAfterAuth && cart.length > 0) {
      setPendingCheckoutAfterAuth(false);
      setPage("cart");
    }
  }

  async function handleSignOut() {
    if (currentUser?.email && cart.length > 0) {
      await supabase.auth.updateUser({ data: { savedCart: cart } });
    }
    await supabase.auth.signOut();
    setCurrentUser(null);
    setUserOrders([]);
    setPendingCheckoutAfterAuth(false);
    setAccountForm({ email: "", password: "", confirmPassword: "" });
    setAccountPromoCodeInput("");
    setCheckoutForm((current) => ({
      ...current,
      email: "",
    }));
    setCheckoutMessage("");
    setCheckoutErrors({});
    setAccountMessage("");
    setAuthMode("signin");
    setIsEditingProfile(false);
  }

  function handleProfileFieldChange(field, value) {
    setProfileForm((current) => ({
      ...current,
      [field]: value,
    }));
  }

  async function handleProfileSave() {
    if (!currentUser?.email) return;

    const updatedMeta = {
      firstName: profileForm.firstName.trim(),
      lastName: profileForm.lastName.trim(),
      country: profileForm.country.trim(),
      address: profileForm.address.trim(),
      address2: profileForm.address2.trim(),
      city: profileForm.city.trim(),
      state: profileForm.state.trim(),
      postalCode: profileForm.postalCode.trim(),
      phone: profileForm.phone.trim(),
      carrierPreference: profileForm.carrierPreference || "",
    };

    await supabase.auth.updateUser({ data: updatedMeta });

    const updatedUser = { ...currentUser, ...updatedMeta };
    setCurrentUser(updatedUser);
    setCheckoutForm((current) => ({
      ...current,
      firstName: updatedUser.firstName,
      lastName: updatedUser.lastName,
      country: updatedUser.country,
      address: updatedUser.address,
      address2: updatedUser.address2,
      city: updatedUser.city,
      state: updatedUser.state,
      postalCode: updatedUser.postalCode,
      phone: updatedUser.phone,
      carrierPreference: updatedUser.carrierPreference || "",
    }));
    setAccountMessage(
      tx(
        "Profile details saved.",
        "Данные профиля сохранены.",
        "Дані профілю збережено.",
        "Profildaten gespeichert.",
        "Datos del perfil guardados."
      )
    );
    setIsEditingProfile(false);
  }

