                                                      <button onClick={() => { if (window.confirm("Delete?")) deleteMessage(msg.id, { fromAdmin: true }); }} className="text-[10px] text-white/15 hover:text-red-300 transition-colors opacity-0 group-hover/del:opacity-100">✕</button>
